window.QB_PAPERS=window.QB_PAPERS||{};window.QB_PAPERS["p719cd39a01"]={"id":"p719cd39a01","name":"2026年山西省公务员录用考试《行测》题（网友回忆版）","year":2026,"region":"山西","count":81,"types":{"新思想":16,"时事政治":3,"马克思主义":2,"逻辑填空":15,"片段阅读":13,"语句表达":2,"图形推理":6,"定义判断":10,"类比推理":5,"逻辑判断":9},"modules":["政治理论","言语理解与表达","判断推理"],"questions":[{"qid":"16070174","no":1,"type":"新思想","module":"政治理论","stem":"<p>推进中国式现代化是一个系统工程，需要统筹兼顾、系统谋划、整体推进，正确处理好一系列重大关系。下列与之相关的表述正确的有（    ）。<br>①活力与秩序：中国式现代化应当而且能够实现活而不乱、活跃有序的动态平衡<br>②守正与创新：守正才能不迷失方向、不犯颠覆性错误，创新才能把握时代、引领时代<br>③战略与策略：要增强策略的前瞻性，准确把握事物发展的必然趋势，以科学的战略预见未来、引领未来<br>④效率与公平：中国式现代化既要创造比资本主义更高的效率，又要更有效地维护社会公平，更好实现效率与公平相兼顾、相促进、相统一</p>","options":[{"k":"A","t":"1项"},{"k":"B","t":"2项"},{"k":"C","t":"3项"},{"k":"D","t":"4项"}],"answer":"C","multi":false,"explanation":"<p>本题考查新思想。<br>2023年10月1日，《求是》杂志发表习近平总书记重要文章《推进中国式现代化需要处理好若干重大关系》，以下简称文章。<br>①正确，文章指出：“五是活力与秩序的关系。在现代化的历史进程中，处理好这对关系是一道世界性难题。中国式现代化应当而且能够实现活而不乱、活跃有序的动态平衡。”<br>②正确，文章指出：“三是守正与创新的关系。守正创新是我们党在新时代治国理政的重要思想方法。守正才能不迷失方向、不犯颠覆性错误，创新才能把握时代、引领时代。”<br>③错误，文章指出：“二是战略与策略的关系。战略与策略是我们党领导人民改造世界、变革实践、推动历史发展的有力武器······要增强战略的前瞻性，准确把握事物发展的必然趋势，敏锐洞悉前进道路上可能出现的机遇和挑战，以科学的战略预见未来、引领未来。”故“策略的前瞻性”表述有误，应为“战略的前瞻性”。<br>④正确，文章指出：“四是效率与公平的关系。中国式现代化既要创造比资本主义更高的效率，又要更有效地维护社会公平，更好实现效率与公平相兼顾、相促进、相统一。”<br>故①②④表述正确，共3项。<br>故正确答案为C。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":0,"pid":"p719cd39a01"},{"qid":"16070156","no":2,"type":"时事政治","module":"政治理论","stem":"<p>制定“十五五”规划建议，系统谋划“十五五”时期经济社会发展，是实现党的二十大描绘的宏伟蓝图、分阶段有步骤推进中国式现代化的需要，意义重大。关于“十五五”规划建议，下列表述正确的有几项？<br>①适度超前建设新型基础设施，推进信息通信网络、全国一体化算力网、重大科技基础设施等建设和集约高效利用<br>②推动量子科技、生物制造、第六代移动通信等成为新的经济增长点<br>③建设法治经济、信用经济，打造市场化法治化国际化一流营商环境<br>④健全与常住人口相匹配的公共资源配置机制，加强县域基本公共服务供给统筹</p>","options":[{"k":"A","t":"1项"},{"k":"B","t":"2项"},{"k":"C","t":"3项"},{"k":"D","t":"4项"}],"answer":"D","multi":false,"explanation":"<p>本题考查新思想。<br>2025年10月23日，中国共产党第二十届中央委员会第四次全体会议通过《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》（以下简称《建议》）。<br>①正确，《建议》在“三、建设现代化产业体系，巩固壮大实体经济根基”部分指出：“（10）构建现代化基础设施体系。加强基础设施统筹规划，优化布局结构，促进集成融合，提升安全韧性和运营可持续性。适度超前建设新型基础设施，推进信息通信网络、全国一体化算力网、重大科技基础设施等建设和集约高效利用，推进传统基础设施更新和数智化改造。”<br>②正确，《建议》在“三、建设现代化产业体系，巩固壮大实体经济根基”部分指出：“前瞻布局未来产业，探索多元技术路线、典型应用场景、可行商业模式、市场监管规则，推动量子科技、生物制造、氢能和核聚变能、脑机接口、具身智能、第六代移动通信等成为新的经济增长点。”<br>③正确，《建议》在“二、‘十五五’时期经济社会发展的指导方针和主要目标”部分指出：“坚持有效市场和有为政府相结合。充分发挥市场在资源配置中的决定性作用，更好发挥政府作用，构建统一、开放、竞争、有序的市场体系，建设法治经济、信用经济，打造市场化法治化国际化一流营商环境，形成既‘放得活’又‘管得好’的经济秩序。”<br>④正确，《建议》在“十一、加大保障和改善民生力度，扎实推进全体人民共同富裕”部分指出：“（44）稳步推进基本公共服务均等化。建立基本公共服务均等化评价标准，完善基本公共服务范围和内容，制定实现基本公共服务均等化的目标、路径、措施，推动更多公共服务向基层下沉、向农村覆盖、向边远地区和生活困难群众倾斜，健全与常住人口相匹配的公共资源配置机制。加强县域基本公共服务供给统筹，完善投入保障长效机制。全面深化事业单位改革。”<br>综上，①②③④表述正确，共4项。<br>故正确答案为D。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":1,"pid":"p719cd39a01"},{"qid":"16070305","no":3,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记强调，要推动森林“水库、钱库、粮库、碳库”更好联动，实现生态效益、经济效益、社会效益相统一。下列表述与这一要求相契合的有几项？<br>①手中有粮，心中不慌<br>②绿水青山就是金山银山<br>③增绿就是增优势，护林就是护财富<br>④环境就是民生，青山就是美丽，蓝天也是幸福</p>","options":[{"k":"A","t":"1项"},{"k":"B","t":"2项"},{"k":"C","t":"3项"},{"k":"D","t":"4项"}],"answer":"C","multi":false,"explanation":"<p>本题考查新思想。<br>①错误，2020年5月23日，习近平总书记在看望参加全国政协十三届三次会议的经济界委员并参加联组会时强调：“对我们这样一个有着14亿人口的大国来说，农业基础地位任何时候都不能忽视和削弱，手中有粮、心中不慌在任何时候都是真理。”故“手中有粮，心中不慌”强调农业对我国的重要性，但并未体现生态效益、经济效益、社会效益相统一。<br>②正确，2005年8月15日，时任浙江省委书记的习近平同志，在湖州市安吉县余村考察时，首次提出“绿水青山就是金山银山”的科学论断。2018年5月18日，习近平总书记在全国生态环境保护大会上发表重要讲话指出：“绿水青山既是自然财富、生态财富，又是社会财富、经济财富。保护生态环境就是保护自然价值和增值自然资本，就是保护经济社会发展潜力和后劲，使绿水青山持续发挥生态效益和经济社会效益。”故“绿水青山就是金山银山”体现了生态效益、经济效益、社会效益相统一。<br>③正确，2023年9月6日，习近平总书记在黑龙江漠河考察时指出：“要坚持造林与护林并重；要树立增绿就是增优势、护林就是护财富的理念，在保护的前提下让老百姓通过发展林下经济增加收入。”“增绿”“护林”体现了生态效益，“增优势”体现了社会效益，“护财富”体现了经济效益，故“增绿就是增优势，护林就是护财富”体现了生态效益、经济效益、社会效益相统一。<br>④正确，2016年1月18日，习近平总书记在省部级主要领导干部学习贯彻党的十八届五中全会精神专题研讨班上发表重要讲话指出：“我讲过，环境就是民生，青山就是美丽，蓝天也是幸福，绿水青山就是金山银山；保护环境就是保护生产力，改善环境就是发展生产力。”“环境”“青山”“蓝天”体现了生态效益，“民生”“美丽”“幸福”体现了社会效益和经济效益，故“环境就是民生，青山就是美丽，蓝天也是幸福”体现了生态效益、经济效益、社会效益相统一。<br>故相契合的有②③④，共3项。<br>故正确答案为C。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":2,"pid":"p719cd39a01"},{"qid":"16069957","no":4,"type":"新思想","module":"政治理论","stem":"<p>党的十八大以来，以习近平同志为核心的党中央坚定不移推进全面从严治党，取得一系列理论创新、实践创新、制度创新成果，构建起全面从严治党体系，开辟了百年大党自我革命新境界。下列关于全面从严治党的表述不准确的是（    ）。</p>","options":[{"k":"A","t":"制度建设要与管党治党需要相适应、与党的各项建设相配套，全方位织密制度的笼子"},{"k":"B","t":"严密党的组织体系，关键是坚持党中央权威和集中统一领导，根本在做到“两个维护”"},{"k":"C","t":"新时代党的建设是以党的组织建设为统领、党的各项建设同向发力综合发力的系统工程"},{"k":"D","t":"着力抓好政治监督、领导班子特别是“一把手”监督、“三重一大”事项监督以及权力集中、资金密集、资源富集等重点领域的监督"}],"answer":"C","multi":false,"explanation":"<p>本题考查新思想。<br>2025年2月16日，《求是》杂志发表习近平总书记重要文章《健全全面从严治党体系》，以下简称文章。<br>A项正确，文章指出：“第四，健全科学完备、有效管用的制度体系。全面从严治党政治性、原则性强，必须有一套科学完备的制度来规范。制度建设要与管党治党需要相适应、与党的各项建设相配套，全方位织密制度的笼子。”<br>B项正确，文章指出：“第一，健全上下贯通、执行有力的组织体系······只有党的组织体系严密起来，党的各级组织政治功能和组织功能充分发挥出来，全面从严治党才能持续向纵深推进。严密党的组织体系，关键是坚持党中央权威和集中统一领导，根本在做到‘两个维护’。”<br>C项错误，文章指出：“······新时代党的建设是以党的政治建设为统领、党的各项建设同向发力综合发力的系统工程，必须以党中央关于党的建设的重要思想、关于党的自我革命的重要思想为根本遵循，坚持和加强党的全面领导和党中央集中统一领导······”故“以党的组织建设为统领”表述有误，应为“以党的政治建设为统领”。<br>D项正确，文章指出：“第三，健全精准发力、标本兼治的监管体系······要突出监督重点，着力抓好政治监督、领导班子特别是‘一把手’监督、‘三重一大’事项监督以及权力集中、资金密集、资源富集等重点领域的监督，切实让特权现象和腐败问题无所遁形。”<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":3,"pid":"p719cd39a01"},{"qid":"16069901","no":5,"type":"新思想","module":"政治理论","stem":"<p>城乡融合发展是中国式现代化的必然要求。关于城乡融合发展，下列说法正确的有几项？<br>①要把乡村振兴战略这篇大文章做好，必须走城乡融合发展之路<br>②在现代化进程中，如何处理好工农关系、城乡关系，在一定程度上决定着现代化的成败<br>③要顺应城乡融合发展大趋势，破除妨碍城乡要素平等交换、双向流动的制度壁垒<br>④振兴乡村，不能就乡村论乡村，还是要强化以工补农、以城带乡，加快形成工农互促、城乡互补、协调发展、共同繁荣的新型工农城乡关系</p>","options":[{"k":"A","t":"1项"},{"k":"B","t":"2项"},{"k":"C","t":"3项"},{"k":"D","t":"4项"}],"answer":"D","multi":false,"explanation":"<p>本题考查新思想。<br>①正确，2018年9月21日，习近平总书记在十九届中央政治局第八次集体学习时讲话指出：“要把乡村振兴战略这篇大文章做好，必须走城乡融合发展之路。我们一开始就没有提城市化，而是提城镇化，目的就是促进城乡融合。要向改革要动力，加快建立健全城乡融合发展体制机制和政策体系。”<br>②正确，2018年9月21日，习近平总书记在十九届中央政治局第八次集体学习时讲话指出：“我一直强调，没有农业农村现代化，就没有整个国家现代化。在现代化进程中，如何处理好工农关系、城乡关系，在一定程度上决定着现代化的成败。”<br>③正确，2022年12月23日，习近平总书记在中央农村工作会议上讲话指出：“要顺应城乡融合发展大趋势，破除妨碍城乡要素平等交换、双向流动的制度壁垒，促进发展要素、各类服务更多下乡，率先在县域内破除城乡二元结构。”<br>④正确，2020年12月28日，习近平总书记在中央农村工作会议上讲话指出：“第六，推动城乡融合发展见实效。振兴乡村，不能就乡村论乡村，还是要强化以工补农、以城带乡，加快形成工农互促、城乡互补、协调发展、共同繁荣的新型工农城乡关系。”<br>综上，①②③④说法正确，共4项。<br>故正确答案为D。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":4,"pid":"p719cd39a01"},{"qid":"16069974","no":6,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记指出，中国愿同世界各国一道，把握信息革命发展的历史主动，携手构建网络空间命运共同体，让互联网更好造福人民、造福世界。关于构建网络空间命运共同体，下列表述正确的是：<br>①尊重网络主权，维护网络安全，共同构建和平、安全、开放、合作的网络空间<br>②全球网络主要由跨国公司提供，网络空间未来应由跨国公司携手经营<br>③倡导发展优先，构建更加普惠繁荣的网络空间<br>④保障数据安全，建立单边、保密的国际互联网治理体系<br>⑤深化网络安全务实合作，有力打击网络违法犯罪行为</p>","options":[{"k":"A","t":"①③⑤"},{"k":"B","t":"①④⑤"},{"k":"C","t":"①②③⑤"},{"k":"D","t":"①②③④⑤"}],"answer":"A","multi":false,"explanation":"<p>本题考查新思想。<br>①正确，2014年11月19日，习近平总书记在向首届世界互联网大会致贺词中强调：“中国正在积极推进网络建设，让互联网发展成果惠及13亿中国人民。中国愿意同世界各国携手努力，本着相互尊重、相互信任的原则，深化国际合作，尊重网络主权，维护网络安全，共同构建和平、安全、开放、合作的网络空间，建立多边、民主、透明的国际互联网治理体系。”<br>②错误，2022年11月7日，国务院新闻办公室发布的《携手构建网络空间命运共同体》白皮书在“三、构建网络空间命运共同体的中国贡献”部分“（三）积极参与网络空间治理”中指出：“中国始终认为，国家不分大小、强弱、贫富，都是平等成员，都有权平等参与国际规则与秩序建构，确保网络空间未来发展由各国人民共同掌握。”同时，全球网络基础设施与治理体系以主权国家为核心主体，跨国公司仅为重要的商业服务提供者，而非“主要提供者”。故“网络空间未来应由跨国公司携手经营”表述错误，应为“确保网络空间未来发展由各国人民共同掌握”。<br>③正确，2023年11月8日，习近平总书记向2023年世界互联网大会乌镇峰会开幕式发表的视频致辞指出：“我们倡导发展优先，构建更加普惠繁荣的网络空间。深化数字领域国际交流合作，加速科技成果转化。加快信息化服务普及，缩小数字鸿沟，在互联网发展中保障和改善民生，让更多国家和人民共享互联网发展成果。”<br>④错误，2015年12月16日，习近平总书记在第二届世界互联网大会开幕式上的讲话中指出：“第五，构建互联网治理体系，促进公平正义。国际网络空间治理，应该坚持多边参与、多方参与，由大家商量着办，发挥政府、国际组织、互联网企业、技术社群、民间机构、公民个人等各个主体作用，不搞单边主义，不搞一方主导或由几方凑在一起说了算······”故“建立单边、保密的国际互联网治理体系”表述错误，应为“国际网络空间治理，应该坚持多边参与、多方参与，由大家商量着办”。<br>⑤正确，2023年11月9日，人民日报发表的文章《共同推动构建网络空间命运共同体迈向新阶段》指出：“‘我们倡导安危与共，构建更加和平安全的网络空间。’只有尊重网络主权，遵守网络空间国际规则，深化网络安全务实合作，有力打击网络违法犯罪行为，加强数据安全和个人信息保护，才能妥善应对科技发展带来的规则冲突、社会风险、伦理挑战，更好维护网络空间安全。”<br>故①③⑤表述正确。<br>故正确答案为A。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":5,"pid":"p719cd39a01"},{"qid":"16069954","no":7,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记强调，要坚持以铸牢中华民族共同体意识为主线，不断推进民族团结进步事业，推动党的民族工作高质量发展。关于铸牢中华民族共同体意识，下列说法正确的有几项?<br>①广泛交往交流交融是推进中华民族共同体建设的重要途径<br>②加强对青少年的历史文化教育，全面推广普及国家通用语言文字，全面推行使用国家统编教材<br>③要坚持和完善民族区域自治制度，逐步完善相关法律法规和差别化区域支持政策，依法保障各族群众合法权益<br>④要引导各族群众不断增强对伟大祖国、中华民族、中华文化、中国共产党、中国特色社会主义的认同</p>","options":[{"k":"A","t":"1项"},{"k":"B","t":"2项"},{"k":"C","t":"3项"},{"k":"D","t":"4项"}],"answer":"D","multi":false,"explanation":"<p>本题考查新思想。<br>2024年9月27日，全国民族团结进步表彰大会在北京举行。习近平总书记出席大会并发表重要讲话。<br>①正确，习近平总书记在讲话中指出：“第四，推动各民族全方位嵌入，积极促进各民族交往交流交融。广泛交往交流交融是推进中华民族共同体建设的重要途径。”<br>②正确，习近平总书记在讲话中指出：“第二，着力构筑中华民族共有精神家园······加强对青少年的历史文化教育，全面推广普及国家通用语言文字，全面推行使用国家统编教材，把中华民族共同体意识从小就植入孩子们的心灵。”<br>③正确，习近平总书记在讲话中指出：“第五，依法治理民族事务，不断提高民族事务治理能力和水平。要坚持和完善民族区域自治制度，逐步完善相关法律法规和差别化区域支持政策，依法保障各族群众合法权益。加强法治宣传教育，引导各族群众增强国家意识、公民意识、法治意识。”<br>④正确，习近平总书记在讲话中指出：“第一，始终坚持党的领导，不断巩固各民族团结奋斗的共同思想政治基础······要引导各族群众不断增强对伟大祖国、中华民族、中华文化、中国共产党、中国特色社会主义的认同，牢固树立休戚与共、荣辱与共、生死与共、命运与共的共同体理念。”<br>故①②③④表述正确，共4项。<br>故正确答案为D。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":6,"pid":"p719cd39a01"},{"qid":"16070207","no":8,"type":"新思想","module":"政治理论","stem":"<p>党的十八大以来，以习近平同志为核心的党中央高度重视海洋工作和海洋事业发展，将海洋强国建设作为实现中华民族伟大复兴的重大战略任务，通盘谋划、整体推进海洋强国建设。关于建设海洋强国，下列表述不准确的是：</p>","options":[{"k":"A","t":"统筹处理人与自然的关系、发展和保护的关系是推进海洋强国建设的重大原则"},{"k":"B","t":"建设海洋强国必须进一步关心海洋、认识海洋、经略海洋，加快海洋科技创新步伐"},{"k":"C","t":"建设强大的现代化海军是建设世界一流军队的重要标志，是建设海洋强国的战略支撑"},{"k":"D","t":"建设海洋强国所需的关键技术主要靠对外开放引进，靠充分发挥国外关键技术经验优势"}],"answer":"D","multi":false,"explanation":"<p>本题考查新思想。<br>A项正确，2024年1月11日，求是网发表的文章《准确把握新形势下海洋资源开发保护要求》指出：“美丽海洋是美丽中国的重要组成部分，碧海蓝天也是金山银山。统筹处理人与自然的关系、发展和保护的关系是推进海洋强国建设的重大原则······”<br>B项正确，2018年6月12日，习近平总书记在山东青岛考察时强调：“海洋经济发展前途无量。建设海洋强国，必须进一步关心海洋、认识海洋、经略海洋，加快海洋科技创新步伐。”<br>C项正确，2017年5月24日，习近平总书记视察海军机关并发表重要讲话。他强调，建设强大的现代化海军是建设世界一流军队的重要标志，是建设海洋强国的战略支撑，是实现中华民族伟大复兴中国梦的重要组成部分。<br>D项错误，2022年4月10日，习近平总书记在中国海洋大学三亚海洋研究院调研考察时，对建设海洋强国作出重要指示，强调要推动海洋科技实现高水平自立自强，加强原创性、引领性科技攻关，把装备制造牢牢抓在自己手里，努力用我们自己的装备开发油气资源，提高能源自给率，保障国家能源安全。故建设海洋强国所需的关键技术不能主要靠对外开放引进，而应加强科技攻关和自主研发。<br>本题为选非题，故正确答案为D。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":7,"pid":"p719cd39a01"},{"qid":"16069911","no":9,"type":"时事政治","module":"政治理论","stem":"<p>党的二十大报告指出，坚持把发展经济的着力点放在实体经济上，推进新型工业化，加快建设制造强国、质量强国、航天强国、交通强国、网络强国、数字中国。关于发展实体经济，下列说法正确的是：<br>①金融是实体经济的血脉，为实体经济服务是金融的天职<br>②要增强资本市场服务实体经济功能，积极有序发展股权融资<br>③要实现实体经济、科技创新、现代金融、人力资源协同发展<br>④要促进实体经济和数字经济深度融合，有序推动实体经济脱实向虚<br>⑤要推动资源要素向实体经济集聚、政策措施向实体经济倾斜、工作力量向实体经济加强</p>","options":[{"k":"A","t":"①②③⑤"},{"k":"B","t":"②③④"},{"k":"C","t":"①②④⑤"},{"k":"D","t":"③④⑤"}],"answer":"A","multi":false,"explanation":"<p>本题考查新思想。<br>①正确，2026年2月1日出版的第3期《求是》杂志发表了习近平总书记的重要文章《走好中国特色金融发展之路，建设金融强国》，文章指出：“······坚持把金融服务实体经济作为根本宗旨。实体经济是金融的根基，金融是实体经济的血脉，服务实体经济是金融的天职······”<br>②正确，2017年7月召开的全国金融会议指出：“金融是国之重器，是国民经济的血脉······要增强资本市场服务实体经济功能，积极有序发展股权融资，提高直接融资比重······”<br>③正确，党的十九大报告在“五、贯彻新发展理念，建设现代化经济体系”部分指出：“必须坚持质量第一、效益优先······着力加快建设实体经济、科技创新、现代金融、人力资源协同发展的产业体系，着力构建市场机制有效、微观主体有活力、宏观调控有度的经济体制，不断增强我国经济创新力和竞争力。”<br>④错误，2026年2月1日出版的第3期《求是》杂志发表了习近平总书记的重要文章《走好中国特色金融发展之路，建设金融强国》，文章指出：“······我国金融必须守好服务实体经济本分，推动高质量发展，决不能脱实向虚。”十五五规划纲要在“第十三章 全方位推进数智技术赋能”部分指出：“促进实体经济和数字经济深度融合。”故“有序推动实体经济脱实向虚”表述有误。<br>⑤正确，《习近平新时代中国特色社会主义思想学习纲要》在“九、以新发展理念引领经济高质量发展”部分指出：“······要加快发展先进制造业，坚定不移建设制造强国。推动互联网、大数据、人工智能同实体经济深度融合，推动资源要素向实体经济集聚、政策措施向实体经济倾斜、工作力量向实体经济加强······”<br>故正确的有①②③⑤。<br>故正确答案为A。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":8,"pid":"p719cd39a01"},{"qid":"16069955","no":10,"type":"新思想","module":"政治理论","stem":"<p>加强数字政府建设是创新政府治理理念和方式、形成数字治理新格局、推进国家治理体系和治理能力现代化的重要举措。下列关于数字政府建设的基本原则，表述正确的有几项?<br>①坚持党的全面领导，充分发挥党总揽全局、协调各方的领导核心作用<br>②坚持以市场为中心，始终把满足人民群众物质生活的迫切需求作为目标<br>③坚持整体协同，强化系统观念，加强系统集成，全面提升数字政府集约化建设水平<br>④坚持数据赋能，建立健全数据治理制度和标准体系，加强数据汇聚融合、共享开放和开发利用</p>","options":[{"k":"A","t":"1项"},{"k":"B","t":"2项"},{"k":"C","t":"3项"},{"k":"D","t":"4项"}],"answer":"C","multi":false,"explanation":"<p>本题考查新思想。<br>2022年6月23日，国务院发布了《关于加强数字政府建设的指导意见》，以下简称《意见》。<br>①正确，《意见》“一、发展现状和总体要求”中“2.基本原则”部分指出：“坚持党的全面领导。充分发挥党总揽全局、协调各方的领导核心作用，全面贯彻党中央、国务院重大决策部署，将坚持和加强党的全面领导贯穿数字政府建设各领域各环节，贯穿政府数字化改革和制度创新全过程，确保数字政府建设正确方向。”<br>②错误，《意见》“一、发展现状和总体要求”中“2.基本原则”部分指出：“坚持以人民为中心。始终把满足人民对美好生活的向往作为数字政府建设的出发点和落脚点······”故“以市场为中心，始终把满足人民群众物质生活的迫切需求作为目标”说法错误，应为“以人民为中心，始终把满足人民对美好生活的向往作为数字政府建设的出发点和落脚点”<br>③正确，《意见》“一、发展现状和总体要求”中“2.基本原则”部分指出：“坚持整体协同。强化系统观念，加强系统集成，全面提升数字政府集约化建设水平，统筹推进技术融合、业务融合、数据融合，提升跨层级、跨地域、跨系统、跨部门、跨业务的协同管理和服务水平······”<br>④正确，《意见》“一、发展现状和总体要求”中“2.基本原则”部分指出：“坚持数据赋能。建立健全数据治理制度和标准体系，加强数据汇聚融合、共享开放和开发利用，促进数据依法有序流动，充分发挥数据的基础资源作用和创新引擎作用，提高政府决策科学化水平和管理服务效率，催生经济社会发展新动能。”<br>故①③④正确，共3项。<br>故正确答案为C。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":9,"pid":"p719cd39a01"},{"qid":"16070220","no":11,"type":"马克思主义","module":"政治理论","stem":"<p>习近平总书记指出，各级干部要深刻懂得用权为民、担责成事、廉洁立身的道理，自觉把担当和自律统一起来，在构建亲清政商关系上亮明态度、付诸行动。关于亲清政商关系，下列表述正确的有几项？<br>①对于领导干部而言，所谓“亲”，就是要坦荡真诚同民营企业接触交往<br>②对于领导干部而言，所谓“清”，就是洁身自好，减少同民营企业家的来往<br>③对于民营企业家而言，所谓“亲”，就是积极主动同各级党委和政府及部门多沟通多交流<br>④对于民营企业家而言，所谓“清”，就是遵纪守法办企业、光明正大搞经营<br>⑤“亲”和“清”本质上是干事和干净的关系，是辩证统一的，完全可以并行不悖</p>","options":[{"k":"A","t":"2项"},{"k":"B","t":"3项"},{"k":"C","t":"4项"},{"k":"D","t":"5项"}],"answer":"C","multi":false,"explanation":"<p>本题考查新思想。<br>①③④正确，②错误，2016年3月4日下午，习近平总书记看望了参加全国政协十二届四次会议的民建、工商联委员，并参加联组会，听取委员们意见和建议。习近平总书记指出：“对领导干部而言，所谓‘亲’，就是要坦荡真诚同民营企业接触交往，特别是在民营企业遇到困难和问题情况下更要积极作为、靠前服务，对非公有制经济人士多关注、多谈心、多引导，帮助解决实际困难。所谓‘清’，就是同民营企业家的关系要清白、纯洁，不能有贪心私心，不能以权谋私，不能搞权钱交易。对民营企业家而言，所谓‘亲’，就是积极主动同各级党委和政府及部门多沟通多交流，讲真话，说实情，建诤言，满腔热情支持地方发展。所谓‘清’，就是要洁身自好、走正道，做到遵纪守法办企业、光明正大搞经营。”故②中“就是洁身自好，减少同民营企业家的来往”表述错误，应为“就是同民营企业家的关系要清白、纯洁，不能有贪心私心，不能以权谋私，不能搞权钱交易”。<br>⑤正确，2025年2月17日，习近平总书记在京出席民营企业座谈会时候指出：“五是进一步构建亲清政商关系。这个问题我讲过多次了，现在仍有不少干部认识不到位、工作片面化简单化。我再次重申，‘亲’和‘清’本质上是干事和干净的关系，是辩证统一的，完全可以并行不悖。”<br>①③④⑤正确，共4项。<br>故正确答案为C。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":10,"pid":"p719cd39a01"},{"qid":"16070227","no":12,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记指出，讲好中国故事，传播好中国声音，展示真实、立体、全面的中国，是加强我国国际传播能力建设的重要任务。关于加强我国国际传播能力建设，下列表述正确的是：<br>①要提升国际传播体系稳定性，防范国际传播格局重构<br>②要全面提升国际传播效能，建强适应新时代国际传播需要的专门人才队伍<br>③要倡导和平的国际舆论环境，不参与国际舆论斗争，塑造谦逊谦和的大国形象<br>④推动走出去、请进来管理便利化，扩大国际人文交流合作</p>","options":[{"k":"A","t":"①②"},{"k":"B","t":"②④"},{"k":"C","t":"①③"},{"k":"D","t":"③④"}],"answer":"B","multi":false,"explanation":"<p>本题考查新思想。<br>①错误，④正确，《中共中央关于进一步全面深化改革、推进中国式现代化的决定》在“十、深化文化体制机制改革”部分中指出：“（41）构建更有效力的国际传播体系。推进国际传播格局重构，深化主流媒体国际传播机制改革创新，加快构建多渠道、立体式对外传播格局。加快构建中国话语和中国叙事体系，全面提升国际传播效能。建设全球文明倡议践行机制。推动走出去、请进来管理便利化，扩大国际人文交流合作。”故“防范国际传播格局重构”表述错误，应为“推进国际传播格局重构”。<br>②正确，③错误，2021年5月31日，习近平总书记在中共中央政治局第三十次集体学习时指出：“我们党历来高度重视对外传播工作……积极推动中华文化走出去，有效开展国际舆论引导和舆论斗争，初步构建起多主体、立体式的大外宣格局······要全面提升国际传播效能，建强适应新时代国际传播需要的专门人才队伍······”故“不参与国际舆论斗争”表述错误，应为“有效开展国际舆论引导和舆论斗争”。<br>综上，②④表述正确。<br>故正确答案为B。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":11,"pid":"p719cd39a01"},{"qid":"16070240","no":13,"type":"新思想","module":"政治理论","stem":"<p>就业是最基本的民生，事关人民群众切身利益，事关经济社会健康发展，事关国家长治久安。关于促进高质量充分就业，下列举措恰当的有几项？<br>①引导退役军人围绕国家重点扶持领域创业<br>②推动农村低收入人口就业帮扶常态化，防止因失业导致规模性返贫<br>③鼓励支持企业吸纳就业、自主创业，统筹用好公益性岗位，确保不出现零就业家庭<br>④对各种类型的就业困难高校毕业生均按照规定给予一定的社会保险补贴<br>⑤提升青年就业服务效能，强化针对性职业指导、职业介绍、技能培训、见习实习，形成衔接校内校外、助力成长成才的服务支撑</p>","options":[{"k":"A","t":"5项"},{"k":"B","t":"4项"},{"k":"C","t":"3项"},{"k":"D","t":"2项"}],"answer":"C","multi":false,"explanation":"<p>本题考查新思想。<br>2024年9月15日，中共中央、国务院发布《关于实施就业优先战略促进高质量充分就业的意见》，以下简称《意见》。<br>①正确，《意见》在“四、完善重点群体就业支持体系”部分指出：“（十）做好退役军人就业服务保障。健全学历教育与职业技能培训、创业培训、个性化培训并行的退役军人教育培训体系······引导退役军人围绕国家重点扶持领域创业。”<br>②正确，《意见》在“四、完善重点群体就业支持体系”部分指出：“（十一）拓宽农村劳动力就业增收空间。壮大县域富民产业，推出一批适应乡村全面振兴需要的新职业，注重引导外出人才返乡、城市人才下乡创业，实施以工代赈，加快形成双向流动、互融互通的统筹城乡就业格局······推动农村低收入人口就业帮扶常态化，防止因失业导致规模性返贫。”<br>③错误，《意见》在“四、完善重点群体就业支持体系”部分指出：“（十二）完善困难人员就业援助制度······鼓励支持企业吸纳就业、自主创业，统筹用好公益性岗位，确保零就业家庭动态清零。”故“确保不出现零就业家庭”表述错误，应为“确保零就业家庭动态清零”。<br>④错误，《意见》在“四、完善重点群体就业支持体系”部分指出：“（十三）优化自主创业灵活就业保障制度······对就业困难人员、离校2年内未就业高校毕业生灵活就业的，按照规定给予一定的社会保险补贴。”故“各种类型的就业困难高校毕业生”表述错误，应为“就业困难人员、离校2年内未就业高校毕业生灵活就业的”。<br>⑤正确，《意见》在“四、完善重点群体就业支持体系”部分指出：“（九）拓展高校毕业生等青年就业成才渠道······提升青年就业服务效能，强化针对性职业指导、职业介绍、技能培训、见习实习，形成衔接校内校外、助力成长成才的服务支撑。”<br>综上，①②⑤说法正确，共3项。<br>故正确答案为C。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":12,"pid":"p719cd39a01"},{"qid":"16069899","no":14,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记指出，对我们这样一个有着14亿人口的大国来说，农业基础地位任何时候都不能忽视和削弱。关于增强粮食等重要农产品供给保障能力，下列说法正确的有几项？<br>①在确保省内耕地保护任务不降低前提下，稳妥有序退出河道内影响行洪安全等的不稳定耕地<br>②加强中小河流治理和大中型灌区建设改造，推进蓄滞洪区关键设施建设和管理机制改革<br>③严格生猪屠宰检疫执法监管，强化重大动物疫病和重点人畜共患病防控<br>④建设现代化防洪减灾体系，全面开展病险水库除险加固<br>⑤加力落实新一轮百亿斤粮食产能提升任务</p>","options":[{"k":"A","t":"5项"},{"k":"B","t":"4项"},{"k":"C","t":"3项"},{"k":"D","t":"2项"}],"answer":"B","multi":false,"explanation":"<p>本题考查新思想。<br>2025年2月23日，《中共中央、国务院关于进一步深化农村改革 扎实推进乡村全面振兴的意见》（以下简称《意见》）发布。<br>①正确，《意见》在“一、持续增强粮食等重要农产品供给保障能力”部分指出：“（三）强化耕地保护和质量提升······稳步推进盐碱地综合利用试点，加强东北黑土区侵蚀沟、南方酸化退化耕地治理。分类推进撂荒地复垦利用。在确保省域内耕地保护任务不降低前提下，稳妥有序退出河道内影响行洪安全等的不稳定耕地。”<br>②④正确，《意见》在“一、持续增强粮食等重要农产品供给保障能力”部分指出：“（五）加强农业防灾减灾能力建设······建设现代化防洪减灾体系，全面开展病险水库除险加固，加强中小河流治理和大中型灌区建设改造，推进蓄滞洪区关键设施建设和管理机制改革。”<br>③正确，《意见》在“一、持续增强粮食等重要农产品供给保障能力”部分指出：“（二）扶持畜牧业稳定发展······落实灭菌乳国家标准，支持以家庭农场和农民合作社为主体的奶业养殖加工一体化发展。严格生猪屠宰检疫执法监管，强化重大动物疫病和重点人畜共患病防控。”<br>⑤错误，《意见》在“一、持续增强粮食等重要农产品供给保障能力”部分指出：“（一）深入推进粮油作物大面积单产提升行动······进一步扩大粮食单产提升工程实施规模，加大高产高效模式集成推广力度，推进水肥一体化，促进大面积增产。加力落实新一轮千亿斤粮食产能提升任务。”故“百亿”表述错误，应为“千亿”。<br>故①②③④表述正确，共4项。<br>故正确答案为B。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":13,"pid":"p719cd39a01"},{"qid":"16070302","no":15,"type":"新思想","module":"政治理论","stem":"<p>建设教育强国，基点在基础教育。基础教育搞得越扎实，教育强国步伐就越稳、后劲就越足。关于加强基础教育，下列举措正确的有几项？<br>①提升寄宿制学校办学条件和管理水平，办好必要的乡村小规模学校<br>②统筹推进市域内高中阶段学校多样化发展，加快扩大普通高中教育资源供给<br>③强化家庭教育主阵地作用，健全学校家庭社会协同育人机制<br>④建立基础教育各学段学龄人口变化监测预警制度，优化中小学和幼儿园布局<br>⑤深入开展县域义务教育优质均衡督导评估，有序推进市域义务教育优质均衡发展</p>","options":[{"k":"A","t":"4项"},{"k":"B","t":"3项"},{"k":"C","t":"2项"},{"k":"D","t":"1项"}],"answer":"A","multi":false,"explanation":"<p>本题考查新思想。<br>2025年1月，中共中央 国务院印发《教育强国建设规划纲要（2024—2035年）》（以下简称《纲要》）。<br>①⑤正确，《纲要》在“三、办强办优基础教育，夯实全面提升国民素质战略基点”部分指出：“（八）推动义务教育优质均衡发展和城乡一体化······提升寄宿制学校办学条件和管理水平，办好必要的乡村小规模学校······深入开展县域义务教育优质均衡督导评估，有序推进市域义务教育优质均衡发展。”<br>②正确，《纲要》在“三、办强办优基础教育，夯实全面提升国民素质战略基点”部分指出：“（九）促进学前教育普及普惠和高中阶段学校多样化发展······统筹推进市域内高中阶段学校多样化发展，加快扩大普通高中教育资源供给。”<br>③错误，《纲要》在“三、办强办优基础教育，夯实全面提升国民素质战略基点”部分指出：“（十）统筹推进‘双减’和教育教学质量提升······强化学校教育主阵地作用，全面提升课堂教学水平，加强对学习困难学生的辅导······”故“强化家庭教育主阵地作用”说法错误，应为“强化学校教育主阵地作用”。<br>④正确，《纲要》在“三、办强办优基础教育，夯实全面提升国民素质战略基点”部分指出：“（七）健全与人口变化相适应的基础教育资源统筹调配机制······建立基础教育各学段学龄人口变化监测预警制度，优化中小学和幼儿园布局。”<br>故①②④⑤说法正确，共4项。<br>故正确答案为A。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":14,"pid":"p719cd39a01"},{"qid":"16069951","no":16,"type":"马克思主义","module":"政治理论","stem":"<p>习近平总书记曾说：“我们要有钉钉子的精神，钉钉子往往不是一锤子就能钉好的，而是要一锤一锤接着敲，直到把钉子钉实钉牢，钉牢一颗再钉下一颗，不断钉下去，必然大有成效。如果东一榔头西一棒子，结果很可能是一颗钉子都钉不上、钉不牢。”这句话最能体现的哲学原理是：<br>①量变与质变辩证统一<br>②肯定与否定辩证统一<br>③主要矛盾与次要矛盾辩证统一<br>④尊重客观规律与发挥主观能动性辩证统一</p>","options":[{"k":"A","t":"①②"},{"k":"B","t":"②③"},{"k":"C","t":"③④"},{"k":"D","t":"①④"}],"answer":"D","multi":false,"explanation":"<p>本题考查马克思主义。<br>①正确，钉钉子要一锤一锤接着敲，直到钉实钉牢，体现了量的积累（每一锤）达到一定程度必然引起质的飞跃（钉牢一颗钉子）；不断钉下去，必然大有成效，体现了量变与质变的辩证统一关系。<br>②错误，“肯定与否定辩证统一”指事物内部包含肯定和否定的因素，要通过辩证否定实现发展。题干强调的是持续用力、循序渐进，并未涉及对事物自身的肯定与否定。<br>③错误，“主要矛盾与次要矛盾辩证统一”指在复杂事物发展过程中要抓关键、抓重点，统筹兼顾。题干强调的是工作方法上的持续性和连贯性，批评“东一榔头西一棒子”，重在防止分散用力，而非区分主次矛盾。<br>④正确，钉钉子要尊重“一锤子钉不好”的客观规律，必须一锤一锤钉，又要发挥主观能动性，一锤一锤接着敲，不断钉下去，只有把二者结合起来，才能取得实效，体现了尊重客观规律与发挥主观能动性的辩证统一关系。<br>故①④表述正确。<br>故正确答案为D。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":15,"pid":"p719cd39a01"},{"qid":"16070214","no":17,"type":"新思想","module":"政治理论","stem":"<p>从“四个全面”战略布局到发展“全链条、全方位、全覆盖”的全过程人民民主，从“全方位、全地域、全过程”开展生态文明建设到“全方位、全过程、全周期”从严治理腐败。一个“全”字，集中凸显了习近平总书记治国理政的哪种思维？</p>","options":[{"k":"A","t":"历史思维"},{"k":"B","t":"底线思维"},{"k":"C","t":"创新思维"},{"k":"D","t":"系统思维"}],"answer":"D","multi":false,"explanation":"<p>本题考查新思想。<br>D项正确，A、B、C三项错误，历史思维是指以历史视角、历史规律看待现实问题，从历史中汲取经验、把握走向，强调以史为鉴、知古鉴今。底线思维是指要立足最不利情况，预判风险、守住边界，强调防风险、守底线、稳大局。创新思维强调突破常规、开拓新思路新方法，强调敢闯敢试、破旧立新。系统思维强调从整体、全局、联系出发，统筹各领域、各环节、各要素，强调整体性、协同性、全覆盖、全过程。题干反复突出“全”，强调整体统筹、全域覆盖、全程贯通、协同联动，正是系统思维的典型体现。<br>故正确答案为D。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":16,"pid":"p719cd39a01"},{"qid":"16070303","no":18,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记指出，要推动公共文化服务标准化、均等化，坚持政府主导、社会参与、重心下移、共建共享，完善公共文化服务体系，提高基本公共文化服务的覆盖面和适用性。关于完善公共文化服务体系，下列举措正确的有几项？<br>①做好文化馆、乡镇（街道）综合文化站、村（社区）综合性文化服务中心等的规划建设<br>②推动优质文化资源向沿海发达地区集中，促进公共文化服务差异化发展<br>③实施全国智慧图书馆体系建设、公共文化云建设等项目<br>④实施广播电视惠民工程，完善农村文化基础设施网络<br>⑤推动各民族文化的传承保护和创新交融，提升民族地区公共文化服务水平</p>","options":[{"k":"A","t":"2项"},{"k":"B","t":"3项"},{"k":"C","t":"4项"},{"k":"D","t":"5项"}],"answer":"C","multi":false,"explanation":"<p>本题考查新思想。<br>2021年9月9日，国务院新闻办公室发布《国家人权行动计划（2021—2025年）》（以下简称《行动计划》）。<br>①正确，《行动计划》在“一、经济、社会和文化权利”部分“（七）文化权利”中指出：“完善公共文化服务基础设施。做好公共图书馆、文化馆、博物馆、美术馆、乡镇（街道）综合文化站、村（社区）综合性文化服务中心等的规划建设。健全各级各类公共文化服务基础设施。”<br>②错误、④正确，《行动计划》在“一、经济、社会和文化权利”部分“（七）文化权利”中指出：“补齐公共文化服务短板。落实国家基本公共服务标准要求，加强基层文化建设，增加供给总量，优化供给结构，推动优质文化资源向农村地区、革命老区、民族地区、边疆地区倾斜，缩小城乡和地区之间公共文化服务差距。实施广播电视惠民工程，完善农村文化基础设施网络。”故“推动优质文化资源向沿海发达地区集中，促进公共文化服务差异化发展”说法有误，应为“推动优质文化资源向农村地区、革命老区、民族地区、边疆地区倾斜，缩小城乡和地区之间公共文化服务差距”。<br>③正确，《行动计划》在“一、经济、社会和文化权利”部分“（七）文化权利”中指出：“推动公共数字文化建设。统筹推进公共文化数字化重点工程建设。实施全国智慧图书馆体系建设、公共文化云建设等项目。”<br>⑤正确，《行动计划》在“四、特定群体权益保障”部分“（一）少数民族权益”中指出：“保障少数民族文化权利。推动各民族文化的传承保护和创新交融，提升民族地区公共文化服务水平。保护和传承少数民族传统文化。做好少数民族古籍保护、抢救、整理、出版和研究工作。开展少数民族古籍数字化建设。办好第六届全国少数民族文艺会演。开展好少数民族语电视剧译制片源捐赠工作。”<br>综上，①③④⑤表述正确，共4项。<br>故正确答案为C。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":17,"pid":"p719cd39a01"},{"qid":"16070154","no":19,"type":"时事政治","module":"政治理论","stem":"<p>“五年来，我们党以巨大的政治勇气和强烈的责任担当，提出一系列新理念新思想新战略，出台一系列重大方针政策，推出一系列重大举措，推进一系列重大工作，解决了许多长期想解决而没有解决的难题，办成了许多过去想办而没有办成的大事，推动党和国家事业发生历史性变革。”这段话最直接体现了马克思主义哲学的哪一观点？</p>","options":[{"k":"A","t":"一切从实际出发"},{"k":"B","t":"人的意识具有能动性"},{"k":"C","t":"人民群众是历史的创造者"},{"k":"D","t":"生产关系反作用于生产力"}],"answer":"B","multi":false,"explanation":"<p>本题考查马克思主义。<br>A项错误，一切从实际出发是马克思主义哲学的根本要求，该观点强调的是理论联系实际，实事求是，从客观实际出发来认识和解决问题。题干强调的是提出新理念新思想新战略、出台方针政策等发挥人的主观能动性，最终推动历史性变革，而并未直接强调这些行动是基于对实际情况的客观认识以及从实际出发来解决问题。<br>B项正确，意识的能动作用是指意识能动地反映世界和通过实践改造世界的能力和作用，其最突出的表现是通过指导实践改造客观世界。题干明确描述了党通过提出新理念新思想新战略、出台方针政策等主动性的行动，推动了党和国家事业的历史性变革，直接体现了人的意识的能动性。<br>C项错误，人民群众是历史的创造者强调的是人民群众在历史发展中的决定性作用。题干强调的是党发挥主观能动性最终推动了党和国家事业的历史性变革，而并未直接强调人民，也并未强调人民群众在历史发展中的决定性作用。<br>D项错误，生产关系反作用于生产力强调的是生产关系对生产力的发展不是消极被动的，而是具有巨大的反作用，其讨论的是生产关系和生产力之间的相互作用关系。题干强调的是“党和国家事业的全面历史性变革”，不局限于经济领域，也不直接讲生产关系调整。<br>故正确答案为B。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":18,"pid":"p719cd39a01"},{"qid":"16069952","no":20,"type":"新思想","module":"政治理论","stem":"<p>下列选项中，习近平用语与其蕴含的思想、观点对应恰当的是：<br>①我将无我，不负人民——全心全意为人民服务<br>②功成不必在我、功成必定有我——方向决定前途，道路决定命运<br>③江山就是人民，人民就是江山——民为邦本<br>④时代是出卷人，我们是答卷人，人民是阅卷人——时代造就英雄，伟大来自平凡</p>","options":[{"k":"A","t":"①②"},{"k":"B","t":"①③"},{"k":"C","t":"②④"},{"k":"D","t":"③④"}],"answer":"B","multi":false,"explanation":"<p>本题考查新思想。<br>①正确，“我将无我，不负人民”出自习近平总书记于2019年3月首次提出的重要表述，源于其回答意大利众议长关于执政理念的提问。该表述集中体现了中国共产党领导人以人民为中心的执政思想，强调为中国人民谋幸福、为中华民族谋复兴的使命担当。“全心全意为人民服务”是中国共产党始终坚持的根本宗旨，体现了党与人民群众的根本关系。其核心要求是将人民利益置于首位，以实现、维护和发展最广大人民根本利益为一切工作的出发点和落脚点。故二者蕴含的思想、观点对应恰当。<br>②错误，“功成不必在我、功成必定有我”出自习近平总书记于2018年4月在深入推动长江经济带发展座谈会上的讲话。该表述意为功绩、事业的成功未必在我手中、在我任期、在我有生之年得到实现，但成功的过程一定有我的参与贡献。“方向决定前途，道路决定命运”出自习近平总书记于2018年12月18日在庆祝改革开放40周年大会上发表的重要讲话，讲的是道路、方向、制度问题。故二者蕴含的思想、观点对应不恰当。<br>③正确，“江山就是人民，人民就是江山”是习近平总书记于2021年2月20日在党史学习教育动员大会上首次完整、公开提出的。这一表述彰显了中国共产党人民至上的根本立场，阐明了人民是国家主人、是历史创造者，党打江山守江山守的是人民的心，始终为人民谋幸福、依靠人民创造历史伟业。“民为邦本”出自《尚书·五子之歌》，意思是老百姓是国家的根本，根本牢固了国家才能安宁，体现了我国早期的民本思想。故二者蕴含的思想、观点对应恰当。<br>④错误，“时代是出卷人，我们是答卷人，人民是阅卷人”出自习近平总书记于2018年1月5日在学习贯彻党的十九大精神研讨班开班式上发表的讲话。这句话深刻回答了新赶考路上“谁来出卷”“谁来答卷”“谁来阅卷”等根本问题，生动诠释了中国共产党一以贯之的初心使命。“时代造就英雄，伟大来自平凡”是习近平总书记于2021年2月25日在全国脱贫攻坚总结表彰大会上发表重要讲话时提出的，它深刻阐释了伟大与平凡、时代与个人的辩证关系，是对奋斗精神、人民力量、英雄观的高度概括。故二者蕴含的思想、观点对应不恰当。<br>故①③表述正确。<br>故正确答案为B。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":19,"pid":"p719cd39a01"},{"qid":"16069958","no":21,"type":"新思想","module":"政治理论","stem":"<p>中国共产党党报党刊的发展历程，与中国共产党的奋斗历程密不可分。下列说法错误的是：</p>","options":[{"k":"A","t":"《布尔塞维克》是解放战争时期中国共产党创办的中央机关刊物"},{"k":"B","t":"《人民日报》由《晋察冀日报》和晋冀鲁豫《人民日报》合并而来"},{"k":"C","t":"《红色中华》创刊于江西瑞金，初期为中华苏维埃共和国临时中央政府机关报"},{"k":"D","t":"《求是》杂志是党中央指导全党全国工作的重要思想理论阵地，前身是中共中央主办的《红旗》杂志"}],"answer":"A","multi":false,"explanation":"<p>本题考查人文常识。<br>A项错误，《布尔塞维克》于1927年10月至1932年7月出版，其名称源自俄语“共产党”的音译，属于中共中央在第二次国内革命战争时期的地下理论机关刊物。而解放战争时期是1946年至1949年。<br>B项正确，1948年5月，晋察冀与晋冀鲁豫边区合并为华北解放区，同年6月15日，《晋察冀日报》和晋冀鲁豫《人民日报》合并为《人民日报》，是中国共产党中央委员会机关报。<br>C项正确，1931年12月11日，《红色中华》创刊于江西瑞金，初期为中华苏维埃共和国临时中央政府机关报，《红色中华》的任务是发挥中央政府对苏维埃运动的积极领导作用。<br>D项正确，《求是》杂志是中国共产党中央委员会主办的机关刊物，是党中央指导全党全国工作的重要思想理论阵地。《求是》杂志创刊于1988年7月1日，其前身是1958年中共中央创办的《红旗》杂志。<br>本题为选非题，故正确答案为A。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":20,"pid":"p719cd39a01"},{"qid":"16069882","no":1,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>中国有着悠久灿烂的文明，同时开创了人类历史上最为<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的现代化进程，中国故事精彩非凡、激动人心，也需要精彩讲述、更好传播。<br>填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"五彩斑斓"},{"k":"B","t":"流光溢彩"},{"k":"C","t":"波澜壮阔"},{"k":"D","t":"汹涌澎湃"}],"answer":"C","multi":false,"explanation":"<p>横线处所填成语搭配“现代化进程”，且根据文意可知，横线处应体现中国现代化进程气势宏大、规模宏伟。C项“波澜壮阔”比喻声势雄壮或规模巨大，多用于形容事业、进程等，与“现代化进程”搭配恰当，且符合文意，当选。<br>A项“五彩斑斓”指多种颜色错杂而繁多耀眼，B项“流光溢彩”形容光彩明亮华丽，跳动闪烁，均多用于形容色彩，与“现代化进程”搭配不当，排除；D项“汹涌澎湃”多形容声势浩大，不可阻挡，常用来形容水流、情绪等，与“现代化进程”搭配不当，排除。<br>故正确答案为C。<br>【文段出处】人民网《以中国话语讲好中国故事（新论）》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":21,"pid":"p719cd39a01"},{"qid":"16069880","no":2,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>《永乐大典》成书于明永乐六年，是中国古代最大的类书，《不列颠百科全书》称其为“世界有史以来最大的百科全书”，共计22937卷，11095册，约3.7亿字，收先秦至明初的各类典籍七八千种，被称为典籍<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>、佚书宝库。</p>","options":[{"k":"A","t":"本源"},{"k":"B","t":"渊薮"},{"k":"C","t":"桂冠"},{"k":"D","t":"文荟"}],"answer":"B","multi":false,"explanation":"<p>顿号提示横线处与“佚书宝库”构成并列，且根据“世界有史以来最大的百科全书”“收先秦至明初的各类典籍七八千种”可知，横线处应体现《永乐大典》汇聚了各类典籍之意，B项“渊薮”指人或事物聚集的地方，置于此处表达典籍汇集之意，为常见表达，符合文意，当选。<br>A项“本源”指事物产生的根源，横线处强调的是典籍的汇聚，而非根源，排除；<br>C项“桂冠”指竞赛中的冠军，与文意无关，排除；<br>D项“文荟”指文化、文艺精华汇聚之所或文化荟萃的状态‌，常被用作机构、场所或活动的名称，“文”与“典籍”重复，排除。<br>故正确答案为B。<br>【文段出处】长江日报《&lt;永乐大典&gt;是怎样上“热搜”的》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":22,"pid":"p719cd39a01"},{"qid":"16069895","no":3,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>未来，数字科技将会持续深度赋能文化产业，数字文化产业新模式、新业态更加丰富，文化产业的产业链、生态链、价值链更为<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。我们应着重培养市场主体，探索建构文化全产业链，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>文化供给与文化需求的错位，引导文化企业坚持社会效益与经济效益的高度统一，不断提升文化产品和服务的供给质量。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"完备 消解"},{"k":"B","t":"完善 拉开"},{"k":"C","t":"完好 弥补"},{"k":"D","t":"完美 避开"}],"answer":"A","multi":false,"explanation":"<p>本题可从第二空入手，横线处词语搭配“错位”，根据 “应着重培养市场主体，探索建构文化全产业链”“引导文化企业坚持社会效益与经济效益的高度统一”可知，横线处应表达要解决、消除文化供给与需求不匹配、不协调的问题。A项“消解”意为消释、消除，与“错位”搭配恰当，符合文意，保留。B项“拉开”指摆开，放开，增加差距，置于此处表达让错位变得更大，与文意相悖，排除；C项“弥补”指补偿、填补，常搭配“短板”“不足”等，与“错位”搭配不当，排除；D项“避开”指躲开、回避，侧重主动绕开问题，不主动解决，文段强调要主动消除错位，与“错位”搭配不当且与文意不符，排除。<br>第一空，代入验证。搭配“产业链、生态链、价值链”，且根据“数字科技将会持续深度赋能文化产业，数字文化产业新模式、新业态更加丰富”可知，横线处应表达相关产业链条变得齐全，完整，A项“完备”指应该有的全都有了，符合文意，当选。<br>故正确答案为A。<br>【文段出处】云南师范大学学报（哲学社会科学版）《“十四五”我国文化产业高质量发展的战略定位与路径选择》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":23,"pid":"p719cd39a01"},{"qid":"16069945","no":4,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>勤劳智慧的黔东南人民始终<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>着与大自然“万物共生”的传统，响应季节变化，熟悉土地秉性，主动顺应、融入大自然生态系统，形成了生态养殖、种植和绿色循环、发展的完整生物链。作为典型的人工生态系统，从江稻鱼鸭复合系统具有保护生物多样性、控制病虫害、调节气候、<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>水源等多种生态功能。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"坚守 涵养"},{"k":"B","t":"遵守 滋润"},{"k":"C","t":"恪守 蓄积"},{"k":"D","t":"信守 保持"}],"answer":"A","multi":false,"explanation":"<p>第一空，搭配“传统”，A项“坚守”指坚定遵守，不背离，B项“遵守”指依照规定行动，不违背，C项“恪守”指严格遵守，均与“传统”搭配恰当，保留。D项“信守”指忠诚地遵守，常搭配“承诺”等，与“传统”搭配不当，排除。<br>第二空，搭配“水源”，A项“涵养”指蓄积并保持（水分等），与“水源”搭配恰当，当选。B项“滋润”指增添水分，使不干枯，与“水源”搭配不当，排除；C项“蓄积”指积聚储存，与“水源”搭配不当，且不及A项“涵养”语义丰富，排除。<br>故正确答案为A。<br>【文段出处】光明网《稻鱼鸭共生：这一人工生态系统何以在黔东南流传千年？》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":24,"pid":"p719cd39a01"},{"qid":"16069936","no":5,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>约有20%的人出生时至少携带一个名为APOE4的基因变异拷贝。该变异使人年老时更易患心脏病，但这种变异却没有被淘汰。研究发现，APOE4基因可能具有抵消其他负面影响的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>好处，如携带APOE4的儿童可以更好地清除肠道寄生虫，而携带这种基因的女性会生育更多的孩子。这种生育优势可能使该致病基因在人类进化过程中得以<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"潜在 延续"},{"k":"B","t":"特殊 发展"},{"k":"C","t":"显性 保存"},{"k":"D","t":"隐性 入选"}],"answer":"A","multi":false,"explanation":"<p>第一空，根据“携带APOE4的儿童可以更好地清除肠道寄生虫”可知，横线处应体现APOE4基因有一些不为人知的好处，这些好处不是马上就能显现出来之意。A项“潜在”指存在于事物内部尚未显露出来的，D项“隐性”指性质或性状不表现在外的，均符合文意，保留。B项“特殊”强调特别、与众不同，与文意不符，排除；C项“显性”指明显表现出来，与文意相悖，排除。<br>第二空，根据“携带这种基因的女性会生育更多的孩子。这种生育优势可能使该致病基因在人类进化过程中”可知，横线处应体现因为这种生育优势，致病基因得以留存下来之意。A项“延续”指照原来样子继续下去，符合文意，当选。D项“入选”指中选、当选，与文意不符，排除。<br>故正确答案为A。<br>【文段出处】《常见阿尔茨海默病基因可能让人类祖先有更多孩子》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":25,"pid":"p719cd39a01"},{"qid":"16069950","no":6,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>马的移动能力强且速度快，有了马的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，人类的畜牧规模必然会有所<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，聚落的大小、位置以及聚落之间的距离也会随之出现一定程度的变化。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"参与 改变"},{"k":"B","t":"帮助 精简"},{"k":"C","t":"协助 扩大"},{"k":"D","t":"介入 增加"}],"answer":"C","multi":false,"explanation":"<p>第一空，根据“有了马的······人类的畜牧规模”可知，横线处应体现马在人类畜牧活动中所起到的作用。A项“参与”指参加，B项“帮助”指替人出力、出主意或给予物质上、精神上的支援，C项“协助”指从旁提供帮助或辅助，均与文意相符，保留。D项“介入”指插入其中进行干预，强调主动干预，与文中“马”这一主体特性不符，排除。<br>第二空，搭配“规模”，且根据“马的移动能力强且速度快”可知，横线处应体现马对人类畜牧规模变化起到积极作用。C项“扩大”指使（范围、规模等）比原来大，与“规模”搭配恰当，且与文意相符，当选。A项“改变”指事物发生显著的差别，置于横线处仅能体现规模发生变化，无法体现是积极的变化还是消极的变化，与C项相较，“扩大”更契合文意，排除；B项“精简”指去掉不必要的，留下必要的，与文意相悖，排除。<br>故正确答案为C。<br>【文段出处】中国社会科学网《骑马术在欧亚草原的流行与在中国的兴起》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":26,"pid":"p719cd39a01"},{"qid":"16069963","no":7,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>现有研究认为，虚拟孵化之所以能培育创业企业，是基于网络聚集了人力和资本资源，帮助创业企业实现了资源<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。事实上，无论是传统孵化还是虚拟孵化，提供资源是孵化平台帮助创业企业克服新生<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>、获取竞争优势的重要方式。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"汇聚 颓势"},{"k":"B","t":"聚积 弱势"},{"k":"C","t":"聚拢 态势"},{"k":"D","t":"聚合 劣势"}],"answer":"D","multi":false,"explanation":"<p>本题可从第二空入手，根据文意及顿号可知，横线处所填词语与“新生”搭配且与后文的“优势”构成反义并列关系，表达创业企业处于新生阶段，面临着竞争中的不利条件或不足之处之意。B项“弱势”指力量弱小的地位或状态，D项“劣势”指在力量或态势上处于比对方不利的条件或地位，置于此处都能表达出新生企业在竞争中相对不利的状况，符合文意，保留。A项“颓势”指衰败、没落的趋势或形势，通常用于描述事物已经出现明显的衰败迹象，但新生企业处于起步和成长初期，只是相对基础薄弱、竞争力不足，而非已呈现出衰败的趋势，与文意不符，排除；C项“态势”指状态和形势，为中性词，无法体现出新生企业面临的不利状况，排除。<br>第一空，搭配“资源”，且根据文意可知，横线处词语表示因网络聚集了人力和资本资源为创业企业带来的积极作用，应与前文的“聚集”在语义上构成对应。D项“聚合”指聚集并结合，强调不仅集中，还能整合为一体，常搭配“资源”，能很好地体现虚拟孵化将人力和资本资源整合为一个有机整体的过程，符合文意，当选。B项“聚积”强调的是通过长时间的积累使数量增多，常搭配“财富”“物资”等，侧重于积累的过程，而文段强调的是虚拟孵化借助网络对人力和资本资源进行整合，并非单纯数量上的积累，与文意不符，排除。<br>故正确答案为D。<br>【文段出处】知网《虚拟孵化对创业企业数字化的使能机理：组织学习视角的案例研究》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":27,"pid":"p719cd39a01"},{"qid":"16069931","no":8,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>在一般印象里，香水是比较晚近的舶来品，但这里的“香水”指的是发展成熟的香精香水。20世纪初，香港的广生行和上海中西大药房<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>引进了淡香精香水“佛罗里达水”，借用欧阳修词中“花露重，草烟低，人家帘幕垂”的句子，命名为“花露水”。这种淡绿色香水主要使用玫瑰与麝香香精，在此后数十年里<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>中国，是中国最流行的香调。所以，有人将花露水称为中国最早的香水，也不能说没有依据。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"先后 遍及"},{"k":"B","t":"率先 风靡"},{"k":"C","t":"抢先 享誉"},{"k":"D","t":"分别 席卷"}],"answer":"B","multi":false,"explanation":"<p>第一空，根据“在一般印象里，香水是比较晚近的舶来品”“有人将花露水称为中国最早的香水”可知，横线处要体现出香港的广生行和上海中西大药房在较早的时候就引进了香水，B项“率先”指带头，首先，C项“抢先”指赶在别人前头，争先，均符合文意，保留。A项“先后”指前后相继，侧重香港的广生行和上海中西大药房这两家引进香水的先后顺序，D项“分别”指分头，各自，均与文意不符，排除。<br>第二空，根据“是中国最流行的香调”可知，横线处要体现出花露水在此后数十年里很流行之意，B项“风靡”指草木随风而倒，形容事物很风行，符合文意，当选。C项“享誉”指在社会上取得声誉，以此体现其品质好口碑好之意，而文段仅仅表达流行之意，与文意不符，排除。<br>故正确答案为B。<br>【文段出处】光明网《中国古代的“香水”》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":28,"pid":"p719cd39a01"},{"qid":"16069929","no":9,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>高山草甸四周海拔较高的陡峭山地往往是不同生态系统的交界处，生存环境和食物资源更为多样，这使得赤狐可以大展拳脚，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>在不同景观的边缘，将捕食效率最大化，同时也将风险降至最低，可谓<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。即使在内蒙古达赉湖、宁夏贺兰山等地，赤狐的洞穴也经常出现。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"逡巡 从容不迫"},{"k":"B","t":"盘桓 张弛有度"},{"k":"C","t":"游走 进退自如"},{"k":"D","t":"驻留 攻守兼备"}],"answer":"C","multi":false,"explanation":"<p>第一空，根据“······在不同景观的边缘，将捕食效率最大化，同时也将风险降至最低”可知，横线处所填词语需体现赤狐能够主动、灵活地穿梭在不同景观边缘的意思，C项“游走”指四处走动、来回移动，置于此处能够体现赤狐的动态性和灵活性，符合文意，保留。A项“逡巡”指有所顾虑而徘徊不前，文段并未体现赤狐有所顾虑，排除；B项“盘桓”指逗留、徘徊，D项“驻留”指在某处暂时停留，两项均强调“停留不走”的状态，与文意不符，排除。<br>第二空，代入验证。C项“进退自如”指无论是前进还是后退都能得心应手，可对应前文“捕食效率最大化”（进）和“风险降至最低”（退），与文意相符，当选。<br>故正确答案为C。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":29,"pid":"p719cd39a01"},{"qid":"16069937","no":10,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>一种能监测心脏术后并发症的新设备可以完成比传统的起搏器更复杂的监测。起搏器只能提供心脏的整体图像，但新设备可以提供更<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的图像，具体显示出心脏哪些区域功能不正常。其上分布的微电极阵列可从心房的多个位置绘制电信号活动，并按需传递电刺激，以便在<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的时候解除房颤，恢复正常心律。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"清晰 需要"},{"k":"B","t":"细致 关键"},{"k":"C","t":"直观 适当"},{"k":"D","t":"完整 凶险"}],"answer":"B","multi":false,"explanation":"<p>第一空，根据横线前转折词“但”及后文“具体显示出心脏哪些区域功能不正常”可知，横线处所填词语应与“整体”构成转折关系，表达新设备提供的图像更具体、更精细之意。B项“细致”指精细周密，符合文意，保留。A项“清晰”指清楚，而文段并未对比图像的清晰度，且其反义词应为“模糊”，无法与“整体”构成转折，排除；C项“直观”指直接观察的，与具体、精细无关，排除；D项“完整”指没有损坏或残缺，与“整体”语义相近，无法构成转折关系，排除。<br>第二空，代入验证。B项“关键”比喻事物最紧要的部分，对事情起决定作用的因素，置于此处能表达在重要、紧急时刻解除房颤之意，逻辑合理，当选。<br>故正确答案为B。<br>【文段出处】《可溶解的心脏监测设备》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":30,"pid":"p719cd39a01"},{"qid":"16069947","no":11,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>史诗类电视剧可以被视为一种文化记忆的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，其目的不仅是呈现特定时期的历史社会文本，而且也是向观众传递镌刻在历史中的社会价值和思想观念。经由历史重现，向观众传递正确的社会价值和思想观念，是史诗类电视剧创制的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"表现 金科玉律"},{"k":"B","t":"投影 玉圭金臬"},{"k":"C","t":"展示 不二之选"},{"k":"D","t":"再现 应有之义"}],"answer":"D","multi":false,"explanation":"<p>第一空，横线处形容“史诗类电视剧”与“文化记忆”之间的关系，根据横线后“呈现特定时期的历史社会文本”可知，横线处应体现出“史诗类电视剧”能够把文化记忆呈现、还原出来之意，A项“表现”意为表示出来，C项“展示”指清楚地摆出来、明显地表现，D项“再现”指（过去的事情）再次出现，均符合文意且与“文化记忆”搭配恰当，保留。B项“投影”意为投射在一个面或一条线上的物体的影子或图形，比喻甲事物在乙事物上面表现出来的迹象，文段并无“投射”之意，排除。<br>第二空，根据横线前“也是向观众传递镌刻在历史中的社会价值和思想观念”及“向观众传递正确的社会价值和思想观念”可知，横线处应体现“史诗类电视剧”应该通过其创作向观众传达正确的社会价值和思想观念之意，D项“应有之义”指应该有的义理，符合文意，当选。A项“金科玉律”比喻必须遵守、不能变更的信条，具有强制性和权威性，置于此处程度过重，排除；C项“不二之选”意为没有比这个选择更好的了，文段并无“选择”的语境，与文意不符，排除。<br>故正确答案为D。<br>【文段出处】光明日报《在酸甜苦辣中向阳而生》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":31,"pid":"p719cd39a01"},{"qid":"17467564","no":12,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>近年来，人们通过电场对磁矩实现精准或概率性质的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，实现了对人脑中突触或神经元功能的模拟，并初步构建了基于自旋的物理神经网络。这一前沿探索不仅挑战了传统计算与信息处理模式的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，还<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>智能科技领域的一场深刻变革。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"测定 范式 彰显出"},{"k":"B","t":"校核 疆域 引发了"},{"k":"C","t":"调控 边界 预示着"},{"k":"D","t":"适配 法则 意味着"}],"answer":"C","multi":false,"explanation":"<p>第一空，根据“通过电场对磁矩实现精准或概率性质的······”可知，横线处需体现“电场对磁矩”的作用，且根据后文“实现了对人脑中突触或神经元功能的模拟，并初步构建了基于自旋的物理神经网络”可知，横线处应体现通过电场来控制磁矩，从而构建物理神经网络之意。C项“调控”指调节控制，在物理学中，“电场调控磁矩”是专业术语，符合文意，保留。A项“测定”指测量确定，侧重于获取数据，而文中强调的是通过操作来实现功能模拟，与文意不符，排除；B项“校核”指校对、核查，通常用于数据或事实的确认，与文意不符，排除；D项“适配”指通过技术手段实现硬件设计思想向可编程逻辑器件的映射过程，通常指两个事物之间的匹配，与文意不符，排除。<br>第二空，代入验证。根据“不仅挑战了传统计算与信息处理模式”“······智能科技领域的一场深刻变革”可知，横线处体现这一前沿探索颠覆了传统的处理模式，C项“边界”指国家之间或地区之间的界线，填入横线体现前沿探索突破了传统模式的应用局限，符合文意，保留。<br>第三空，代入验证。根据“还······智能科技领域的一场深刻变革”可知，横线处所填词语应体现这种探索引发或预示深刻变革。“‘预示着’变革”意为根据现状推断未来将有变革，能够体现前沿探索的前瞻性特点，符合文意，C项当选。<br>故正确答案为C。<br>【文段出处】科学通报《基于自旋的智能器件与物理神经网络进展》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":32,"pid":"p719cd39a01"},{"qid":"14143359","no":13,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>这些“山环水绕”的地方虽然山不高，水的形态也无太大差别，但这里是自然优美的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。这里有花岗岩、石灰岩、红色砂岩三大造景岩石，每一种都造就了独具<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的美，如花岗岩的雄浑，石灰岩的秀美，红色砂岩造就的赤壁丹霞······然而，这块“山环水绕”之地，永远在<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>中展现出无穷的多样性，如花岗岩造就的黄山式的景观在江西三清山上再现，红色砂岩造就的广东仁化碧水丹崖式的风景在福建泰宁重演。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"代表 生态 丰富性"},{"k":"B","t":"特例 风情 共同性"},{"k":"C","t":"范例 特色 同一性"},{"k":"D","t":"典范 个性 统一性"}],"answer":"D","multi":false,"explanation":"<p>第一空，根据“这里有花岗岩、石灰岩、红色砂岩三大造景岩石，每一种都造就了独具······的美”可知，横线处意在表达这些“山环水绕”的地方能够体现出自然优美之意。A项“代表”指显示同一类的共同特征的人或事物，C项“范例”指可以当作典范的事例，D项“典范”指可以作为学习、效仿标准的人或事物，均符合文意，保留。B项“特例”指特殊的事例，由前文“虽然山不高，水的形态也无太大差别”可知，文段并未体现这里有“特殊”之意，排除。<br>第二空，根据“如花岗岩的雄浑，石灰岩的秀美，红色砂岩造就的赤壁丹霞······”可知，横线处应体现三大造景岩石造就的美各有独特之处，C项“特色”指事物所表现的独特的色彩、风格，D项“个性”指事物的特性，均能够体现出“不一样”之意，保留。A项“生态”指生物在一定的自然环境下生存和发展的状态，也指生物的生理特性和生活习性，与文中造景岩石的地质景观之美无关，且无法体现出独特之处，排除。<br>第三空，根据“如花岗岩造就的黄山式的景观在江西三清山上再现，红色砂岩造就的广东仁化碧水丹崖式的风景在福建泰宁重演”可知，横线处应体现不同地域的同类景观存在共通规律与内在特质。D项“统一性”指共有的特质和特性，侧重内在规律一致、共有特质相通，与文意相符，且能与“多样性”对应，当选。C项“同一性”指具有完全相同的性质，侧重强调事物间毫无差异，与后文“多样性”表意矛盾，排除。<br>故正确答案为D。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":33,"pid":"p719cd39a01"},{"qid":"16070308","no":14,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>人工智能技术飞速发展，逐渐向人类智能水平逼近。科学家们在研究过程中愈发清晰地意识到，许多棘手的问题并非单凭一家公司之力就能成功解决。除了至今<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的“电车难题”外，还有日益重要的价值观<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>问题——当AI拥有了自主设定目标的能力时，又该如何确保这些由AI自行确定的目标符合人类利益、与人类价值观相<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>？<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"争论不休 构建 吻合"},{"k":"B","t":"流口常谈 践行 出入"},{"k":"C","t":"悬而未决 对齐 契合"},{"k":"D","t":"束手无策 匹配 切合"}],"answer":"C","multi":false,"explanation":"<p>第一空，搭配“电车难题”，且根据“许多棘手的问题并非单凭一家公司之力就能成功解决”可知，横线处所填成语应表达“电车难题”至今没有解决之意，C项“悬而未决”指一直拖在那里，没有得到解决，符合文意，保留。A项“争论不休”比喻双方或多方对某一个问题各执一端，讨论不出最终的结果，谁也不肯停下来，B项“流口常谈”指人人挂在嘴上的老话，均无法体现没有解决之意，排除；D项“束手无策”形容遇到问题时毫无解决的办法，程度过重，且主语通常为人，一般表述为“令人束手无策的‘电车难题’”，排除。<br>第二空，代入验证。搭配“价值观”，C项“对齐”指的是使两个或多个事物在位置、方向或功能上达到整齐、一致或协调的状态，与“价值观”搭配恰当，保留。<br>第三空，代入验证。根据“、”可知，横线处所填词语与“符合”意思接近，C项“契合”指投合，符合，符合文意，当选。<br>故正确答案为C。<br>【文段出处】微信公众号：中国战略新兴产业《从互撕到约谈：马斯克与奥特曼的“AI冷战”突然破冰？》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":34,"pid":"p719cd39a01"},{"qid":"16070307","no":15,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>考古学的早期实践是自然史的延伸，就是以进化模式来安排考古材料。人类的历史和文化被看作是一种<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的过程，世界各地的文化发展遵循相同的轨迹，文化差异是由发展速率的快慢所造成。这种直线进化论存在明显弱点，导致种族主义考古学<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，把原住民文化看作生物学因素造成的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>现象，无法发展到更高级的阶段。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"自然 泛滥 滞后"},{"k":"B","t":"加速 盛行 反常"},{"k":"C","t":"累进 流行 落后"},{"k":"D","t":"演变 胜出 极端"}],"answer":"C","multi":false,"explanation":"<p>第一空，根据“以进化模式来安排考古材料”“文化差异是由发展速率的快慢所造成”“这种直线进化论”可知，横线处应体现不断进化之意。C项“累进”指以一定方式逐步增加，D项“演变”指发展变化，均符合文意，保留。A项“自然”指自由发展，不受外界干预，侧重自发产生，无法体现进化之意，与文意不符，排除；B项“加速”指加快速度，与文意不符，排除。</p><p>第二空，根据文意可知，横线处应体现种族主义考古学比较盛行之意，C项“流行”指广泛传布、盛行，可以体现种族主义考古学比较盛行之意，符合文意，保留。D项“胜出”指在比赛或竞争中胜过对手，文段并未体现战胜对手之意，与文意不符，排除。<br>第三空，代入验证。根据“无法发展到更高级的阶段”可知，横线处应体现水平较低、不高级之意，C项“落后”指不先进，符合文意，当选。<br>故正确答案为C。<br>【文段出处】齐鲁学刊《考古学如何重建上古史》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":35,"pid":"p719cd39a01"},{"qid":"16069943","no":16,"type":"片段阅读","module":"言语理解与表达","stem":"<p>晚安牛奶的最大卖点在于“高褪黑素含量”。有品牌标明“褪黑素含量：12500pg/盒”，1pg等于万亿分之一克。而褪黑素的有效剂量在0.1~0.3毫克，这意味着需要喝约8000盒这种牛奶才能达到治疗剂量，因此晚安牛奶助眠更依赖于其安慰剂效应。如果某人有轻微的失眠困扰，还达不到临床上失眠的诊断标准，又能够排除器质性或精神疾病因素导致的失眠，个体比较相信晚安牛奶，或者喝后有效，在这种有益无害的前提下，不妨食用。<br>这段文字意在强调：</p>","options":[{"k":"A","t":"晚安牛奶的助眠效果主要源自心理作用"},{"k":"B","t":"晚安牛奶能助眠是商家的虚假宣传"},{"k":"C","t":"多喝晚安牛奶才能起到助眠作用"},{"k":"D","t":"晚安牛奶有较好的助眠效果"}],"answer":"A","multi":false,"explanation":"<p>文段首先通过晚安牛奶的最大卖点，引出“高褪黑素含量”话题，之后通过数据对比指出品牌标明的褪黑素含量远远达不到褪黑素的治疗剂量，随后通过结论词“因此”引出结论，即晚安牛奶助眠更依赖于其安慰剂效应。最后进行补充说明，指出在某些轻微、非器质性或精神疾病因素导致的失眠且在本人相信等情况下可以食用。故文段重在强调晚安牛奶助眠效果的真正来源是安慰剂作用，即心理作用，对应A项。<br>B项，“商家的虚假宣传”文段并未提及，无中生有，排除；<br>C项，“多喝晚安牛奶才能起到助眠作用”非重点，虽然文段提到“需要喝约8000盒”，但这只是为了证明晚安牛奶的褪黑素含量低，排除；<br>D项，“晚安牛奶有较好的助眠效果”偏离重点，文段重点强调“晚安牛奶的助眠效果主要靠安慰剂作用”，排除。<br>故正确答案为A。<br>【文段出处】中华网《网红“晚安牛奶”真能助眠吗？医生：喝8000瓶才有效》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":36,"pid":"p719cd39a01"},{"qid":"16069878","no":17,"type":"片段阅读","module":"言语理解与表达","stem":"<p>智能社会的演进模糊了社会心态与社会行为的边界，呈现出线上线下虚实共生、心态风险与行动风险交织缠绕的特征，这对社会心态的治理策略与治理工具提出了新的挑战。社交软件的分享机制与算法推荐规律，都以对人类心理特征的精准利用为前提。此类技术往往把复杂的人类互动过程简化为点赞、转发等二元化的态度立场或简单行为，虽然便利了个体表达观点，却可能导致网络行为高度两极化，让许多事实错误但情绪饱满的虚假信息快速传播，成为网络空间治理的一大顽疾。<br>这段文字意在强调：</p>","options":[{"k":"A","t":"智能社会对社会心态治理提出了新的挑战"},{"k":"B","t":"智能化加速了从社会心态到社会行为的转化"},{"k":"C","t":"社交软件的算法可能导致网络行为高度两极化"},{"k":"D","t":"智能社会当务之急是要加强网络空间治理"}],"answer":"A","multi":false,"explanation":"<p>文段开篇介绍了智能社会演进所呈现的特征，并指出这对社会心态的治理提出了新挑战。随后指出社交软件的分享机制与算法推荐规律会简化人类的互动行为，导致网络行为高度两极化，让虚假信息传播，成为网络空间治理的一大顽疾，即对前文进行了解释说明。故文段重点在首句，强调智能社会的演进对社会心态治理提出了新挑战，对应A项。<br>B项，“加速了从社会心态到社会行为的转化”无中生有，文段未提及，排除；<br>C项，“可能导致网络行为高度两极化”对应分述句部分，非重点，且缺少文段主题词“智能社会”，排除；<br>D项，文段的问题是“智能社会对社会心态的治理提出新挑战”，若想提对策，也应该是针对“社会心态”，“要加强网络空间治理”偏离文段核心，对策不具备针对性，排除。<br>故正确答案为A。<br>【文段出处】光明日报《以“智”臻“善”：社会心态治理的发展趋势》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":37,"pid":"p719cd39a01"},{"qid":"16069876","no":18,"type":"片段阅读","module":"言语理解与表达","stem":"<p>人形机器人的传感器像是人类的眼睛、耳朵和皮肤，扮演着感知器官的角色。视觉传感器通过摄像头捕捉环境图像；声音传感器接收并解析语音指令；力觉传感器仿效人体的力觉感受，精确感知与外界的接触力；触觉传感器模仿人类触觉，精准感知物体的形状和硬度。控制系统是人形机器人的大脑，借助计算单元和智能算法处理数据并作出决策。多种智能算法的应用让机器人越来越接近人类，比如利用深度神经网络，处理视觉、语音识别等任务。<br>根据这段文字，对“人形机器人的设计原理”概括最准确的是：</p>","options":[{"k":"A","t":"借助多功能传感器实现智能化处理"},{"k":"B","t":"仿生学与机械工程的有机融合"},{"k":"C","t":"赋予精准触觉，提升感知能力"},{"k":"D","t":"传感技术与控制理论的集成突破"}],"answer":"D","multi":false,"explanation":"<p>文段首先指出人形机器人的传感器扮演感知器官的角色，并具体介绍视觉、声音、力觉和触觉传感器的作用。随后指出控制系统如同人类大脑，借助计算单元和智能算法处理数据并作出决策，并说明智能算法的应用使其更接近人类。故文段为并列结构，从传感器与控制系统两个角度论述了人形机器人的设计原理，对应D项。<br>A项“多功能传感器”、C项“触觉”和“提升感知能力”均仅对应传感器部分，未提及“控制系统”，表述片面，排除；<br>B项，“机械工程”文段未提及，无中生有，排除。<br>故正确答案为D。<br>【文段出处】人民日报《探索人形机器人的奥秘（开卷知新）》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":38,"pid":"p719cd39a01"},{"qid":"16069930","no":19,"type":"片段阅读","module":"言语理解与表达","stem":"<p>在我国，对农业生产造成重大危害的多数昆虫都具有迁飞性。草地贪夜蛾、黏虫等具有“春夏北迁，秋冬南迁”的习性。由于昆虫个体小、重量轻，飞行能力有限，远距离迁飞主要借助气流运载。季风、台风、西太平洋副热带高压的位置与强度变化等因素都会对害虫的迁飞扩散产生重要影响。每年春夏，害虫大军从中南半岛等地随西南季风迁飞入我国，之后又随西南季风或东南季风暖湿气流继续北上。到了秋冬，草地贪夜蛾、黏虫等为逃避低温环境，只好迁回温暖的南方。这是昆虫逃避不良环境条件的一种生存对策。<br>这段文字重在说明害虫大军迁飞的：</p>","options":[{"k":"A","t":"地域密码"},{"k":"B","t":"季节规律"},{"k":"C","t":"环境影响"},{"k":"D","t":"生存策略"}],"answer":"B","multi":false,"explanation":"<p>文段开篇引出话题“多数昆虫都具有迁飞性”，随后提出观点，草地贪夜蛾、黏虫等具有“春夏北迁，秋冬南迁”的习性，即害虫大军迁飞的季节规律。后文对其进行原因解释，从季风、台风、西太平洋副热带高压的位置与强度变化等因素具体论述如何影响其迁飞的季节规律，文段最后一句通过“这”对前文“逃避低温环境”进行补充说明。故文段重在说明害虫大军迁飞的季节规律，对应B项。<br>A项“地域密码”文段并非重点描述，虽然提及南北方，但“春夏北迁，秋冬南迁”重点是强调季节的规律，排除；<br>C项“环境影响”对应“季风、台风、西太平洋副热带高压的位置与强度变化等因素”，为原因解释部分内容，非重点，排除；<br>D项“生存策略”出现在尾句，是对“逃避低温环境”进行的补充说明，并非全文重点，排除。<br>故正确答案为B。<br>【文段出处】中国农业科学院植物保护研究所《一探究竟 “虫军”迁飞的气象“密码”》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":39,"pid":"p719cd39a01"},{"qid":"16069964","no":20,"type":"片段阅读","module":"言语理解与表达","stem":"<p>斑翅果蝇的雌虫会在多种软皮水果中产卵，其幼虫在果实内取食，导致水果腐烂。近日，科研人员利用“基因剪刀”技术将影响斑翅果蝇性别发育的基因修改成让雌虫无法正常产卵但对雄虫无影响的版本后，斑翅果蝇的绝大多数后代都会继承这个基因变化，实现基因驱动。科学家认为，人为实现基因驱动，让特定基因在生物群体中传播开来，可以控制有害生物的数量或增强濒危物种的抗病能力。此前已有研究团队用相关方法消灭传播疟疾的蚊子，此次用于斑翅果蝇这种农业害虫尚属首次。<br>这段文字主要介绍了：</p>","options":[{"k":"A","t":"“基因剪刀”技术是一项高效的抗虫害技术"},{"k":"B","t":"“基因剪刀”技术增强了濒危物种的抗病能力"},{"k":"C","t":"通过基因驱动可以控制有害生物的数量"},{"k":"D","t":"研究人员用“基因剪刀”技术对抗斑翅果蝇"}],"answer":"D","multi":false,"explanation":"<p>文段首先指出斑翅果蝇雌虫产卵会危害软皮水果，接着说明科研人员用“基因剪刀”技术修改其性别发育基因，实现基因驱动，随后介绍基因驱动具有控制有害生物数量或增强濒危物种抗病能力的作用，尾句进一步强调，此次将该技术用于斑翅果蝇这种农业害虫是首次尝试。故文段围绕“基因剪刀”技术与“斑翅果蝇”展开，重点强调研究人员运用“基因剪刀”技术对抗斑翅果蝇这一具体研究，对应D项。<br>A项，“高效的抗虫害技术”侧重对技术本身的属性评价，但文段并未提及该技术是否“高效”，且文段核心是介绍该技术针对斑翅果蝇的具体应用实践，选项缺少文段主题词“斑翅果蝇”，偏离文段重点，排除；<br>B项，“增强了濒危物种的抗病能力”仅为“基因剪刀”技术实现基因驱动后可能带来的效果之一，并非文段所阐述的核心内容，表述片面且非重点，且缺少文段主题词“斑翅果蝇”，排除；<br>C项，“控制有害生物的数量”仅为基因驱动可能带来的效果之一，并非文段所阐述的核心内容，表述片面且非重点，且缺少文段主题词“基因剪刀”技术与“斑翅果蝇”，排除。<br>故正确答案为D。<br>【文段出处】新华网《美国研究用“基因剪刀”对抗农业害虫斑翅果蝇》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":40,"pid":"p719cd39a01"},{"qid":"16069948","no":21,"type":"语句表达","module":"言语理解与表达","stem":"<p>如今，网络和数字媒介已成为未成年人生活的基本环境。短视频以沉浸式体验让他们轻松获得各种热点、热梗和表情包，“老铁”“666”等迅速进入他们的话语体系，甚至成为特定圈层的身份标识。在各大社交媒体上，家长们担心“孩子不好好说话”，老师们交流“如何引导学生正确用语”。诙谐幽默的网络语言在丰富人类表达的同时，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。在“人机共生”时代，如何培育未成年人的语言文化素养值得重视。<br>填入画横线处最恰当的是：</p>","options":[{"k":"A","t":"也成为人们理解文化和世界的重要方式"},{"k":"B","t":"也对原有规范的语言文化体系造成冲击"},{"k":"C","t":"更需要思考机器智能环境下的文化素养提升问题"},{"k":"D","t":"越来越多的人感受到“文字失语”的困扰"}],"answer":"B","multi":false,"explanation":"<p>本题为语句填空题，横线在文段中间，需结合前后文进行分析。文段开篇指出各种网络语言进入了未成年人的话语体系，但与此同时，家长与老师对此种现象表示了担心并给予正确引导。可知，网络语言虽丰富了人类的表达，但仍有负面影响。B项中“对原有规范的语言文化体系造成冲击”准确对应概括了前文中“不好好说话”“引导学生正确用语”等问题，并且与后文“重视如何培育未成年人语言文化素养”这一对策高度契合，当选。<br>A项，“理解文化和世界”文段并未提及，无中生有，排除；<br>C项，缺少文段核心话题“语言”，且“机器智能”文段并未提及，无中生有，排除；<br>D项，“文字失语”指因网络文化和流行语的影响，导致语言表达能力下降的现象，但横线之前强调“丰富人类表达”，与前文语义矛盾，无法衔接，排除。<br>故正确答案为B。<br>【文段出处】《“人机共生”时代更须注重语言规范》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":41,"pid":"p719cd39a01"},{"qid":"16069873","no":22,"type":"片段阅读","module":"言语理解与表达","stem":"<p>“低空风怪”也叫下击暴流，是一股从雷暴云中快速下沉的强烈气流。如同瀑布一泻千里直击山石，“风怪”在触及地面后向四周爆发出强大的冲击力。当“风怪”呼啸而下时，速度最高可达每秒100米，比高铁还快。不仅如此，它还会在低空形成猛然四散的强风，击中地面时爆发出的水平风力最大可达17级，足以掀翻火车、轮船。“风怪”造成的大风会在几百米内风向突变，对飞机起降危害很大。<br>接下来作者最有可能讲述的是：</p>","options":[{"k":"A","t":"“低空风怪”的定义及其特征"},{"k":"B","t":"“低空风怪”威力强、危害大"},{"k":"C","t":"能否对“低空风怪”作出预警"},{"k":"D","t":"“低空风怪”与龙卷风的差异"}],"answer":"C","multi":false,"explanation":"<p>本题为接语选择题，需要在通读全文的基础上，重点关注文段最后讨论的核心话题。文段开篇引出“低空风怪”这一话题，随后分别论述了其冲击力强、风速快、风力大的特点，尾句强调“低空风怪”的危害，即对飞机起降危害性很大。故下文应该继续围绕“低空风怪”的危害性进一步延伸，最有可能探讨预警“低空风怪”的相关话题，C项当选。<br>A项“‘低空风怪’的定义及其特征”与B项“‘低空风怪’威力强、危害大”均为前文已论述过的内容，后文不会再次论述，排除；<br>D项，“龙卷风”文段并未提及，与前文衔接不当，排除。<br>故正确答案为C。<br>【文段出处】光明网·文摘报《降服“低空风怪”》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":42,"pid":"p719cd39a01"},{"qid":"16069894","no":23,"type":"片段阅读","module":"言语理解与表达","stem":"<p>在深度学习的过程中，实际确定误差并非易事。为解决这一问题，当前深度学习领域应用“损失函数”实现误差最小化，即在人工智能的学习过程中，找到能够最小化损失函数值的参数。但损失函数的形式会随具体情况而有所不同，难以全面掌握其特性，因此需要引入微分。微分主要用于分析某个变量的变化如何影响函数的值。通过对损失函数进行微分，可以明了参数变化时损失函数值的变化，进而调整参数值，让损失函数的值尽可能小。在针对性地进行编程后，人工智能能够自动完成上述任务。<br>对这段文字概括最恰当的是：</p>","options":[{"k":"A","t":"通过对损失函数进行微分，深度学习能实现误差最小化"},{"k":"B","t":"引入微分后，损失函数能帮助人工智能实现自主深度学习"},{"k":"C","t":"损失函数在深度学习中主要用于确定误差"},{"k":"D","t":"损失函数对深度学习的参数优化具有重要意义"}],"answer":"A","multi":false,"explanation":"<p>文段开篇介绍在深度学习过程中确定实际误差并非易事，接下来指出用“损失函数”实现误差最小化，随后“但”转折引出损失函数形式会随具体情况而有所不同，难以全面掌握其特性，紧接着通过“因此”强调需要引入微分，后文继续说明对损失函数微分能明确参数变化对损失值的影响，进而调整参数值让损失函数的值尽可能小，且进行针对性编程后人工智能就可自动完成任务。故文段核心在于对损失函数进行微分能帮助深度学习实现误差最小化，对应A项。<br>B项，文段重点是“误差最小化”，并非“实现自主深度学习”，偏离文段中心，排除；<br>C、D两项，均缺少“微分”这一主题词，偏离文段中心，排除。<br>故正确答案为A。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":43,"pid":"p719cd39a01"},{"qid":"16070239","no":24,"type":"片段阅读","module":"言语理解与表达","stem":"<p>当人们将光照程度作为城市发达程度的衡量标准时，大都市的星光也正在“黯淡消失”。曾几何时，夜晚璀璨的星空带给人无限的遐思，但是随着城市化进程的加快，越来越多生活在城市里的人发现，星星似乎“消失不见”了。天文学家表示，近年来光污染状况迅速恶化，超过三分之一的人类看不到夜空中明亮的银河。发光二极管和其他形式的照明正以惊人的速度照亮夜空。由于光污染的加剧，20年后人类可能无法看到夜晚的星空。<br>最适合做这段文字标题的是：</p>","options":[{"k":"A","t":"星光黯淡：寻找消失的星星"},{"k":"B","t":"光污染：亮了城市，暗了星空"},{"k":"C","t":"星星点灯：照不亮城市的夜空"},{"k":"D","t":"光污染：让星星们“无处可藏”"}],"answer":"B","multi":false,"explanation":"<p>文段开篇介绍人们将光照程度作为衡量城市发达程度的标准，同时大都市的星光在“黯淡消失”，接着指出随着城市化进程加快，城市的星星似乎“消失不见”了。后文通过天文学家的观点，强调城市光污染状况迅速恶化，部分人类已经看不到夜空中明亮的银河，最后指出未来人类可能看不见夜晚的星空，故文段整体围绕“光污染”展开，介绍其照亮城市的同时也“暗淡”了星空，对应B项。<br>A项，未提及核心话题“光污染”，且“寻找消失的星星”文段并未提及，无中生有，排除；<br>C项，未提及核心话题“光污染”，且“星星点灯”文段并未提及，无中生有，排除；<br>D项，“无处可藏”与文意相悖，且缺少对城市的影响，表述片面，排除。<br>故正确答案为B。<br>【文段出处】中国科学报《光污染：亮了城市，暗了星空》科技日报《光污染或致20年后难见星空》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":44,"pid":"p719cd39a01"},{"qid":"16069897","no":25,"type":"片段阅读","module":"言语理解与表达","stem":"<p>绿色供应链是一种在整个供应链中综合考虑环境影响和资源效率的现代管理模式。它以绿色制造理论和供应链管理技术为基础，涉及供应商、生产商、销售商、消费者和回收商，目的是使产品从物料获取、加工、包装、仓储、运输、使用到报废处理的整个过程，对环境影响最小，资源利用率最高。资源材料是绿色供应链的基础，其可持续性供给是实现绿色供应链的根本条件。<br>根据这段文字，可以推出的是：</p>","options":[{"k":"A","t":"传统供应链对环境影响的关注度较低"},{"k":"B","t":"应用绿色供应链，生产商和供应商最为关键"},{"k":"C","t":"绿色供应链的核心目标是增强可持续发展"},{"k":"D","t":"若资源材料供给不可持续，绿色供应链则难以实现"}],"answer":"D","multi":false,"explanation":"<p>A项，文段仅介绍了绿色供应链“综合考虑环境影响”，未提及传统供应链对环境影响的关注度，无中生有，排除；<br>B项，根据“它以绿色制造理论和供应链管理技术为基础，涉及供应商、生产商、销售商、消费者和回收商”可知，“生产商和供应商最为关键”表述过于绝对，排除；<br>C项，根据“目的是使产品从物料获取、加工、包装、仓储、运输、使用到报废处理的整个过程，对环境影响最小，资源利用率最高”可知，“核心目标是增强可持续发展”表述错误，排除；<br>D项，根据“资源材料是绿色供应链的基础，其可持续性供给是实现绿色供应链的根本条件”可知，若资源材料供给不可持续，作为根本条件缺失，绿色供应链则难以实现，表述正确，当选。<br>故正确答案为D。<br>【文段出处】中国知网《打造绿色供应链 如何让电机“转”得更省》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":45,"pid":"p719cd39a01"},{"qid":"16070287","no":26,"type":"片段阅读","module":"言语理解与表达","stem":"<p>20世纪中叶，分子生物学诞生，开启了在分子水平上研究生命及其活动的现代生命科学时代。这个时期的研究者采用“碎片化”的模式来研究生命及其生理或病理活动。但是，研究者逐渐认识到，生命活动并非是由一个个基因或蛋白质“零件”独立完成的，而是建立在生命体内众多基因、蛋白质和其他化学小分子形成的复杂相互作用之上；对于高等生物而言，除了分子层面复杂的相互作用网络外，还有着细胞、组织和器官等不同介观层面各种组分之间的相互作用。<br>根据这段文字，可以推出：</p>","options":[{"k":"A","t":"生命活动是一种复杂系统的整体行为"},{"k":"B","t":"低等生物的生命活动由基因独立完成"},{"k":"C","t":"分子层面的研究是理解高等生物的关键"},{"k":"D","t":"现代科学主要采用“碎片化”模式研究生命活动"}],"answer":"A","multi":false,"explanation":"<p>A项，根据“生命活动并非是由一个个基因或蛋白质‘零件’独立完成的，而是建立在生命体内众多基因、蛋白质和其他化学小分子形成的复杂相互作用之上······还有着细胞、组织和器官等不同介观层面各种组分之间的相互作用”可知，表述正确，当选；<br>B项，根据“生命活动并非是由一个个基因或蛋白质‘零件’独立完成的”可知，文段是一个普遍性的陈述，并未区分低等生物和高等生物，尽管后文提及高等生物有额外的介观层面相互作用，但并不意味着低等生物的生命活动可以由基因独立完成，无中生有，排除；<br>C项，根据“除了分子层面复杂的相互作用网络外，还有着细胞、组织和器官等不同介观层面各种组分之间的相互作用”可知，除了“分子层面的研究”，还存在“细胞、组织和器官等不同介观层面”，未提及分子层面的研究是理解高等生物的“关键”，偷换逻辑，排除；<br>D项，根据“20世纪中叶，分子生物学诞生······这个时期的研究者采用‘碎片化’的模式来研究生命及其生理或病理活动”和“但是，研究者逐渐认识到，生命活动并非是······”可知，20 世纪中叶使用了“碎片化”的模式，后来研究者逐渐认识到该模式的弊端，故无法得出现代科学“主要采用”“碎片化”模式研究生命活动，排除。<br>故正确答案为A。<br>【文段出处】中国网《生命大科学：从微观到介观的组学研究》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":46,"pid":"p719cd39a01"},{"qid":"16069944","no":27,"type":"片段阅读","module":"言语理解与表达","stem":"<p>近年来，一系列具有人文情怀的文化综艺类节目集体走红。在融媒体时代，文化综艺类节目如何创新成了摆在创作者面前的一道难题。创新要找到令年轻人感兴趣的点进行嫁接，但又不能丢掉主流媒体的审美、价值观和社会责任。文化综艺的创新，应该走文化传统和现代时尚相结合之路，不能脱离对传统经典文化的传承凭空打造所谓现代时尚，而是要把传统与时代精神相结合，走进人民群众最接地气的生活，在寓教于乐中让人受到启迪。<br>下列选项与这段文字意思不符的是：</p>","options":[{"k":"A","t":"文化综艺类节目的创新要扎根人民、扎根生活"},{"k":"B","t":"文化综艺类节目要以传承传统文化为首要目的"},{"k":"C","t":"文化综艺类节目不能流于说教而忽视其娱乐性"},{"k":"D","t":"文化综艺类节目创新要关注年轻人的精神需求"}],"answer":"B","multi":false,"explanation":"<p>A项，根据“走进人民群众最接地气的生活”可知，“扎根人民、扎根生活”与文意相符，排除；<br>B项，根据“应该走文化传统和现代时尚相结合之路······要把传统与时代精神相结合”可知，“以传承传统文化为首要目的”文段并未提及，无中生有，当选；<br>C项，根据“在寓教于乐中让人受到启迪”可知，“不能流于说教而忽视其娱乐性”与文意相符，排除；<br>D项，根据“创新要找到令年轻人感兴趣的点进行嫁接”可知，“创新要关注年轻人的精神需求”与文意相符，排除。<br>本题为选非题，故正确答案为B。<br>【文段出处】中国文化报《文化综艺如何“玩转”传统文化？》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":47,"pid":"p719cd39a01"},{"qid":"16069967","no":28,"type":"片段阅读","module":"言语理解与表达","stem":"<p>近日，一种名叫“RoboCap”的机器人胶囊问世，体积相当于维生素大小，一端在容器中装载有效药物，表面涂有明胶，可调节其在特定pH下溶解。当涂层溶解时，pH的变化会触发“RoboCap”胶囊内部的一个微型马达旋转，有助于胶囊进入粘液并移位。胶囊上覆盖着小螺柱，可以像牙刷一样刷掉粘液。旋转运动还可帮助侵蚀携带药物的隔室，将药物释放到消化道。也就是说，该胶囊的“机器人帽”到达小肠时，会旋转并穿过粘液屏障，使胶囊携带的药物进入肠道内的细胞。研究人员表示，机器人胶囊有朝一日或能取代注射给药的方式。<br>这段文字未涉及机器人胶囊的：</p>","options":[{"k":"A","t":"应用前景"},{"k":"B","t":"适用对象"},{"k":"C","t":"工作原理"},{"k":"D","t":"内部结构"}],"answer":"B","multi":false,"explanation":"<p>A项，根据“研究人员表示，机器人胶囊有朝一日或能取代注射给药的方式”可知，“应用前景”文段有所提及，排除；<br>B项，“适用对象”在文段中并未提及，无中生有，当选；<br>C项，根据“当涂层溶解时，pH的变化会触发‘RoboCap’胶囊内部的一个微型马达旋转，有助于胶囊进入粘液并移位。胶囊上覆盖着小螺柱，可以像牙刷一样刷掉粘液。旋转运动还可帮助侵蚀携带药物的隔室，将药物释放到消化道”可知，“工作原理”文段有所提及，排除；<br>D项，根据“一端在容器中装载有效药物，表面涂有明胶”“胶囊内部的一个微型马达”“携带药物的隔室”可知，“内部结构”文段有所提及，排除。<br>本题为选非题，故正确答案为B。<br>【文段出处】科技日报《机器人胶囊可将药物送入消化道》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":48,"pid":"p719cd39a01"},{"qid":"16070179","no":29,"type":"片段阅读","module":"言语理解与表达","stem":"<p>一年中的大部分时间，成年棕熊都是离群索居的动物。但当大量鲑鱼洄游到湖中繁殖时，常常会有几十头棕熊同时聚集在湖边。过高的种群密度和相对有限的理想捕鱼位置，决定了它们必须竞争进食序列。在这个巨大的“餐桌”周围，进食的座次是由实力来决定的，成年公熊之间常常为了争夺捕鱼位置在湖畔发生激烈打斗，胜者赢得一切。在这个时期，湖畔通常是被雄性棕熊所占据的，当雌性带着幼年棕熊靠近时，狂暴的公熊会驱赶它们，幼熊易遭到撕咬而死亡。<br>由这段文字无法推出：</p>","options":[{"k":"A","t":"成年棕熊在争夺食物时竞争非常激烈"},{"k":"B","t":"成年棕熊的进食序列主要由实力决定"},{"k":"C","t":"鲑鱼繁殖期的湖畔对幼熊会更加危险"},{"k":"D","t":"雌熊带幼熊靠近湖畔是为了捕食鲑鱼"}],"answer":"D","multi":false,"explanation":"<p>A项：根据“成年公熊之间常常为了争夺捕鱼位置在湖畔发生激烈打斗”可知，符合文意，排除；<br>B项：根据“在这个巨大的‘餐桌’周围，进食的座次是由实力来决定的”可知，符合文意，排除；<br>C项：根据“当大量鲑鱼洄游到湖中繁殖时，······在这个时期······当雌性带着幼年棕熊靠近时，狂暴的公熊会驱赶它们，幼熊易遭到撕咬而死亡”可知，符合文意，排除；<br>D项：文段仅指出“当雌性带着幼年棕熊靠近时，狂暴的公熊会驱赶它们”，但并未提及它们靠近的目的是捕食鲑鱼，无中生有，当选。<br>本题为选非题，故正确答案为D。<br>【文段出处】中国国家地理网《堪察加棕熊 为森林“运氮”的鲑鱼猎手》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":49,"pid":"p719cd39a01"},{"qid":"16069928","no":30,"type":"语句表达","module":"言语理解与表达","stem":"<p>①一段时间里，长视频葆有一种艺术优越感，认为台网联动就是把影视作品切成片段挪到网上<br>②这种长短阵营划分实际上是专业作品和民间段子的区分<br>③但在当今短视频崛起的网络视频生态中，长视频不可再孤芳自赏，而应打开视野，与更多短视频及受众进行联结交流<br>④剧场化不是让长视频成为网络视听阵营的“孤勇者”，而是在精品化战略基础上思考如何利用短视频为作品铺垫引流<br>⑤的确，长视频是一种综合艺术，包含文学、戏剧、音乐、歌舞等多种艺术元素<br>⑥网络视频原无长短之分，只因短视频的崛起，专业生产的影视作品才以长视频的概念区别于用户生产模式的短视频<br>将以上6个句子重新排列，语序正确的是：</p>","options":[{"k":"A","t":"⑥④①②③⑤"},{"k":"B","t":"④⑥②①⑤③"},{"k":"C","t":"⑤①②③⑥④"},{"k":"D","t":"①⑤③②④⑥"}],"answer":"B","multi":false,"explanation":"<p>观察选项，确定首句。①句指出长视频葆有艺术优越感及对台网联动的认识，④句对“剧场化”下定义，指出剧场化是在精品化战略基础上思考如何利用短视频为长视频作品铺垫引流，⑥句说明长短视频划分的由来，三句均可作首句，故保留A、B、D三项。⑤句以“的确”开头，“的确”指完全确实，多用于佐证前文观点，故不适合直接作首句，排除C项。<br>继续观察发现，②句出现指代词“这”，可考虑指代词捆绑解题。②句核心围绕“长短视频的阵营划分”展开，前文需围绕此话题论述。观察A、B、D三项可知，②句前分别为①、③、⑥句。⑥句介绍因短视频的崛起才有了长短视频之分，与②句话题一致，可构成指代词捆绑，B项当选。①句介绍长视频葆有艺术优越感，③句介绍当下长视频的发展方向，二者均无法与②句构成指代词捆绑，排除A、D两项。<br>故正确答案为B。<br>【文段出处】光明日报《影视节目创作传播：长短视频互利共生》</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":50,"pid":"p719cd39a01"},{"qid":"17467529","no":1,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性。</p><p><img src=\"assets/img/timu/19cecde8d05601e.png\" class=\"fig\" style=\"width:600px;height:278px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B","multi":false,"explanation":"<p>元素组成不同，且无明显属性规律，考虑数量规律。观察发现，题干图形出现明显封闭区域，优先考虑数面。题干图形的面数量依次为10、9、8、？、6、5，故“？”处图形的面数量应为7，只有B项符合。<br>故正确答案为B。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":51,"pid":"p719cd39a01"},{"qid":"16070177","no":2,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律：</p><p><img src=\"assets/img/timu/19cec5168b029b8.png\" class=\"fig\" style=\"width:600px;height:259px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>元素组成不同，且无明显属性规律，考虑数量规律。观察发现，题干图形均由黑块和白块构成，且分堆明显，考虑部分数。第一组图，黑块部分数明显无规律，白块部分数为2、3、4，依次递增1；第二组图，前两幅图白块部分数依次为2、3，故问号处图形白块部分数应为4，对应D项。<br>故正确答案为D。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":52,"pid":"p719cd39a01"},{"qid":"16070180","no":3,"type":"图形推理","module":"判断推理","stem":"<p>把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：</p><p><img src=\"assets/img/timu/19cec5274264808.png\" class=\"fig\" style=\"width:500px;height:391px;\"></p>","options":[{"k":"A","t":"①②④，③⑤⑥"},{"k":"B","t":"①②⑥，③④⑤"},{"k":"C","t":"①③⑥，②④⑤"},{"k":"D","t":"①④⑥，②③⑤"}],"answer":"C","multi":false,"explanation":"<p>本题为分组分类题目。元素组成相似，且相同元素“圆”重复出现，优先考虑样式规律中的遍历。观察发现，图①③⑥中的圆均位于图形内部，图②④⑤中的圆均位于图形外部，即图①③⑥为一组，图②④⑤为一组。<br>故正确答案为C。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":53,"pid":"p719cd39a01"},{"qid":"16070178","no":4,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：</p><p><img src=\"assets/img/timu/19cecb2815e1f85.png\" class=\"fig\" style=\"width:600px;height:244px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"C","multi":false,"explanation":"<p>元素组成相似，且相同线条重复出现，优先考虑样式规律中的加减同异。九宫格优先横向看，观察发现，第二行图形只能先将图2左右翻转，然后与图1求异，才可得到图3；经验证，第一行也符合此规律；第三行应用此规律，因此？处图形应将图2左右翻转，然后与图1求异得到，只有C项符合。<br>故正确答案为C。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":54,"pid":"p719cd39a01"},{"qid":"16070184","no":5,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：</p><p><img src=\"assets/img/timu/19cec53710eaad8.png\" class=\"fig\" style=\"width:600px;height:268px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B","multi":false,"explanation":"<p>本题考查立体拼合。第一组图的图一由图二和图三拼合而成，第二组图的图一也应由图二与“？”处图形拼合而成，对应B项。 </p><p><img src=\"assets/img/timu/19cec54a2136ef2.png\" class=\"fig\" style=\"width:600px;height:103px;\"></p><p>故正确答案为B。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":55,"pid":"p719cd39a01"},{"qid":"16070185","no":6,"type":"定义判断","module":"判断推理","stem":"<p>回归效应，是指极端样本在后续观测中更接近总体均值的趋势，表现为个体极端特征随时间推移逐渐减弱。<br>根据上述定义，下列体现了回归效应的是：</p>","options":[{"k":"A","t":"龙生龙，凤生凤，老鼠的儿子会打洞"},{"k":"B","t":"尺寸小的豌豆子代会变大，尺寸大的豌豆子代会变小"},{"k":"C","t":"一对父母身高近两米，他们的孩子成年后身高也近两米"},{"k":"D","t":"某篮球运动员平均每场得分为20分，但在某场比赛中得了40分"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“更接近总体均值”、“个体极端特征”、“随时间推移逐渐减弱”。<br>第二步：逐一分析选项。<br>A项：龙生龙、凤生凤强调的是遗传稳定性，个体极端特征没有减弱，反而保持，不符合定义，排除；<br>B项：尺寸小（极端偏小）的豌豆子代变大，尺寸大（极端偏大）的豌豆子代变小，个体极端特征随时间推移逐渐减弱，都向中间的总体尺寸均值靠拢，符合定义，当选；<br>C项：父母身高近两米，孩子身高也近两米，个体极端特征没有减弱，反而保持，不符合定义，排除；<br>D项：只说了一场得40分（极端高分），但没有后续数据说明得分向20分的均值回归，不符合定义，排除。<br>故正确答案为B。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":56,"pid":"p719cd39a01"},{"qid":"16070186","no":7,"type":"定义判断","module":"判断推理","stem":"<p>可编程物质是指一种可以根据用户输入或自主感应而以编程方式来改变自身物理性质的物质。<br>根据上述定义，下列不涉及可编程物质的是：</p>","options":[{"k":"A","t":"某智能水泥通过内嵌的传感器，自主控制水泥应力的释放以保持建筑物结构稳定"},{"k":"B","t":"某智能布料由高分子复合纤维织成，输入不同电压会改变其电场，从而根据预设编码显现不同图案"},{"k":"C","t":"通过添加纳米颗粒和化学反应物，某新型水泥可以实现自动修复裂缝和损坏，从而延长建筑的寿命"},{"k":"D","t":"某智能玻璃使用Socket网络编程技术，可根据外部光照强度和内部信号来改变透明度，调节室内光线以节省能源"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“根据用户输入或自主感应”、“以编程方式”、“改变自身物理性质”。<br>第二步：逐一分析选项。<br>A项：智能水泥通过内嵌的传感器自主控制应力的释放来保持建筑物结构稳定，属于“自主感应”、“以编程方式”、“改变自身物理性质”，符合定义，排除；<br>B项：智能布料通过输入不同电压改变电场，根据预设编码显现不同图案，属于“用户输入”、“以编程方式”、“改变自身物理性质”，符合定义，排除；<br>C项：新型水泥通过添加纳米颗粒和化学反应物实现自动修复，属于材料本身的化学特性，不符合“根据用户输入或自主感应”、“以编程方式”，不符合定义，当选；<br>D项：智能玻璃通过网络编程技术，根据外部光照强度和内部信号来改变透明度，属于“自主感应”、“以编程方式”、“改变自身物理性质”，符合定义，排除。<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":57,"pid":"p719cd39a01"},{"qid":"16070190","no":8,"type":"定义判断","module":"判断推理","stem":"<p>心理学中的自我关怀，也被称作自我怜悯、自我同情，指能够保护个体远离自我批评、反刍思维的一种积极的自我认知态度。当个体处在困难、挫折、痛苦、失望等情景中时，对自己消极的状态能够保持开放和友善的态度，能够安抚和关心自己。<br>根据上述定义，下列未体现自我关怀的是：</p>","options":[{"k":"A","t":"此情可待成追忆，只是当时已惘然"},{"k":"B","t":"僵卧孤村不自哀，尚思为国戍轮台"},{"k":"C","t":"丈夫生世会几时，安能蹀躞垂羽翼"},{"k":"D","t":"莫因诗卷愁成谶，春鸟秋虫自作声"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“能够保护个体远离自我批评、反刍思维的一种积极的自我认知态度”、“当个体处在困难、挫折、痛苦、失望等情景中时”、“对自己消极的状态能够保持开放和友善的态度”、“能够安抚和关心自己”。<br>第二步：逐一分析选项。<br>A项：意思是“此时此景为什么要现在才追忆，只因为当时心中只是一片茫然。”说明诗人沉浸在过去的遗憾、消极情绪中反复回味，是典型的反刍思维，不符合“能够保护个体远离自我批评、反刍思维的一种积极的自我认知态度”、“当个体处在困难、挫折、痛苦、失望等情景中时”、“对自己消极的状态能够保持开放和友善的态度”、“能够安抚和关心自己”，不符合定义，当选；<br>B项：意思是“穷居孤村，躺卧不起，不为自己的处境而感到哀伤，心中还想着替国家戍守边疆。”其中“僵卧孤村”体现出诗人目前处于挫折和困难中，但“不自哀”体现出诗人身处逆境却不自我哀怜、不自我批评，是一种积极的态度，符合“能够保护个体远离自我批评、反刍思维的一种积极的自我认知态度”、“当个体处在困难、挫折、痛苦、失望等情景中时”，符合定义，排除；<br>C项：意思是“大丈夫一辈子能有多长时间，怎么能畏缩不前、垂头丧气，像鸟儿收起翅膀那样憋屈？”体现出诗人面对挫折时的不甘心和对自己的鼓励，是一种积极的态度，符合“当个体处在困难、挫折、痛苦、失望等情景中时”、“对自己消极的状态能够保持开放和友善的态度”，符合定义，排除；<br>D项：意思是“不要忧愁自己写的愁苦之诗会成为吉凶的预言，春天的鸟儿和秋天的虫儿都会发出自己的声音。”体现出诗人面对愁绪、消极状态时，不自我批评，能够接纳并安抚自己，符合“能够保护个体远离自我批评、反刍思维的一种积极的自我认知态度”、“当个体处在困难、挫折、痛苦、失望等情景中时”、“对自己消极的状态能够保持开放和友善的态度”、“能够安抚和关心自己”，符合定义，排除。<br>本题为选非题，故正确答案为A。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":58,"pid":"p719cd39a01"},{"qid":"16070188","no":9,"type":"定义判断","module":"判断推理","stem":"<p>凯伊效应是指当一束高粘度的假塑性流体倾倒至固体表面时，固体表面会把液束向上反弹出去。其原理为快速下落的液束冲击下方堆积的黏性流体，流体表面因为受到冲击粘度变小，受到撞击后形成一个酒窝状的凹坑，同时粘度降低的表面充当了润滑剂的作用，最终使得下落的液束被反弹出去。<br>根据上述定义，下列属于凯伊效应的是：</p>","options":[{"k":"A","t":"用肥皂水冲洗勺子，肥皂水碰到勺子后会沿着勺子曲面流下去"},{"k":"B","t":"在喷水池喷出的水柱上放乒乓球，水柱会托举乒乓球向上跳跃"},{"k":"C","t":"水流冲过土壤中的孔隙或裂缝时，形成了类似管道的水流通道"},{"k":"D","t":"将洗发水从高处快速倒向桌面，堆积的洗发水会突然跳起一束"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“高粘度的假塑性流体倾倒至固体表面”、“液束向上反弹出去”。<br>第二步：逐一分析选项。<br>A项：肥皂水碰到勺子后沿着勺子曲面流下去，液束没有反弹，不符合“液束向上反弹出去”，不符合定义，排除；<br>B项：水柱托举乒乓球向上跳跃，不涉及液束反弹，不符合“液束向上反弹出去”，不符合定义，排除；<br>C项：水流冲过孔隙或裂缝形成类似管道的水流通道，不涉及液束反弹，不符合“液束向上反弹出去”，不符合定义，排除；<br>D项：将洗发水从高处快速倒向桌面，洗发水是高粘度假塑性流体，符合“高粘度的假塑性流体倾倒至固体表面”，堆积的洗发水突然跳起一束，符合“液束向上反弹出去”，符合定义，当选。<br>故正确答案为D。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":59,"pid":"p719cd39a01"},{"qid":"17467530","no":10,"type":"定义判断","module":"判断推理","stem":"<p>复冰现象是指当冰的表面受压，压力令其熔点降低，使得冰化成水，一旦压力消失，熔点提高至原来的水平，水又变为冰的现象。<br>根据上述定义，下列不属于复冰现象的是：</p>","options":[{"k":"A","t":"将两块水平放置的冰砖面对面压实，松手后两块冰砖粘在了一起"},{"k":"B","t":"在一块很大的冰上放一条金属线，金属线两端分别连着两个重物，金属线缓慢穿越冰块而且不会将其切开"},{"k":"C","t":"在滑冰场上滑冰时，冰刀留下道道痕迹，但很快刀痕会全部消失，留下完好如初的冰面"},{"k":"D","t":"水结冰时，所释放的热量在其内部形成压力、产生气泡，这使得结成的冰看上去不透明"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“冰受压化成水”、“压力消失水又变为冰”。<br>第二步：逐一分析选项。<br>A项：两块冰砖压实，说明冰在受压时先化成了水，松开粘一块说明刚刚化的水又结冰了，符合“冰受压化成水”、“压力消失水又变为冰”，符合定义，排除；<br>B项：金属线能够穿过冰，说明冰受压化成了水，金属线穿过之后压力解除，但冰不会被切开，说明水又结冰，符合“冰受压化成水”、“压力消失水又变为冰”，符合定义，排除；<br>C项：刀痕消失，说明冰刀离开冰面后，压力消失，水膜重新结冰，冰面恢复平整，符合“冰受压化成水”、“压力消失水又变为冰”，符合定义，排除；<br>D项：水结冰时内部产生压力和气泡，仅仅是水结冰的单向凝固过程，并没有体现冰化水现象，不符合“冰受压化成水”、“压力消失水又变为冰”，不符合定义，当选。<br>本题为选非题，故正确答案为D。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":60,"pid":"p719cd39a01"},{"qid":"16070192","no":11,"type":"定义判断","module":"判断推理","stem":"<p>新污染物筛查主要有两类：非靶向筛查是不针对特定的目标污染物，基于全扫描分析获取对样品成分的表达；疑似筛查是根据先验的化学结构信息和质谱采集的特征发现样品中可能存在的化学物质。<br>根据上述定义，下列最能体现疑似筛查的是：</p>","options":[{"k":"A","t":"小肖利用全二维气相色谱—质谱法分析废水样品，发现污水处理过程中产生了苯并三唑类化合物"},{"k":"B","t":"课题组筛查化工园区土壤中的污染物，对识别到的化合物的检测频率和相对含量进行打分，最终选出了36种优先污染物"},{"k":"C","t":"研究小组筛查了潜在内分泌干扰物列表中的化学物，发现一半以上的个人护理产品中含有与发育损害或内分泌干扰有关的成分"},{"k":"D","t":"吴教授采用效应导向分析方法筛查出石油和香烟浸出液中导致芳基烃受体（AhR）反应的组分，并鉴定出这些组分中导致AhR反应的化合物"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>非靶向筛查：“不针对特定的目标污染物”、“基于全扫描分析获取对样品成分的表达”；<br>疑似筛查：“根据先验的化学结构信息和质谱采集的特征”、“发现样品中可能存在的化学物质”。<br>第二步：逐一分析选项。<br>A项：小肖利用全二维气相色谱—质谱法分析废水样品发现了苯并三唑类化合物，符合“不针对特定的目标污染物”、“基于全扫描分析获取对样品成分的表达”，符合非靶向筛查定义，不符合疑似筛查定义，排除；<br>B项：对识别到的化合物的检测频率和相对含量进行打分，最终“选出”了36种优先污染物，“选出”意味着不是新发现的，是对已有识别结果的后续处理，不符合“发现样品中可能存在的化学物质”，不符合疑似筛查定义，排除；<br>C项：筛查潜在内分泌干扰物列表中的化学物，符合“根据先验的化学结构信息和质谱采集的特征”，发现一半以上的个人护理产品中含有与发育损害或内分泌干扰有关的成分，符合“发现样品中可能存在的化学物质”，符合疑似筛查定义，当选；<br>D项：吴教授采用“效应导向”分析方法筛查出石油和香烟浸出液中导致芳基烃受体（AhR）反应的组分，是从效应倒推成分，不符合“根据先验的化学结构信息和质谱采集的特征”，不符合疑似筛查定义，排除。<br>故正确答案为C。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":61,"pid":"p719cd39a01"},{"qid":"16070198","no":12,"type":"定义判断","module":"判断推理","stem":"<p>某些电介质在沿一定方向上受到外力的作用而变形时，其内部会产生极化现象，同时在它的两个相对表面上出现正负相反的电荷。当外力去掉后，它又会恢复到不带电的状态，这种现象被称为正压电效应。相反，当在电介质的极化方向上施加电场，电介质会发生变形，电场去掉后，电介质的变形随之消失，这种现象被称为逆压电效应。<br>根据上述定义，下列体现了逆压电效应的是：</p>","options":[{"k":"A","t":"超声波清洗是利用超声波的机械振动来清洗物体表面"},{"k":"B","t":"液晶显示器利用液晶材料改变光通过的方向和强度，从而显示动态图像"},{"k":"C","t":"打火机的打火器被按下后能瞬间产生高压，在极小的间隙下击穿空气，点燃气体"},{"k":"D","t":"风力发电机工作时将风的动能转化为风轮轴的机械能，发电机在风轮轴的带动下旋转发电"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出定义关键词。</p><p>正压电效应：“电介质受外力作用变形”、“内部产生极化现象”、“两个相对表面出现正负相反电荷”、“外力去掉后恢复不带电状态”；</p><p>逆压电效应：“在电介质的极化方向上施加电场”、“电介质发生变形”、“电场去掉后，变形随之消失”。</p><p>第二步：逐一分析选项。</p><p>A项：超声波清洗是利用超声波的机械振动来清洗物体表面，超声波发生器在电介质极化方向施加电场，使电介质发生变形产生机械振动，符合“在电介质的极化方向上施加电场”、“电介质发生变形”，符合“逆压电效应”的定义，当选；</p><p>B项：液晶显示器利用液晶材料改变光通过的方向和强度，从而显示动态图像，液晶显示器仅通过电场改变液晶分子排列来控光，未涉及电介质的变形，不符合“在电介质的极化方向上施加电场”、“电介质发生变形”，不符合“逆压电效应”的定义，排除；</p><p>C项：打火机的打火器被按下后能瞬间产生高压，是对压电材料施加外力使其产生电荷，符合“电介质受外力作用变形”、“内部产生极化现象”、“两个相对表面出现正负相反电荷”，压力去掉后，电介质不带电，符合“外力去掉后恢复不带电状态”，符合“正压电效应”的定义，不符合“逆压电效应”的定义，排除；</p><p>D项：风力发电机将“风的动能”转化为“机械能”，发电机在风轮轴的带动下旋转发电，没有在电介质的极化方向上施加电场，不符合“在电介质的极化方向上施加电场”、“电介质发生变形”、“电场去掉后，变形随之消失”，不符合“逆压电效应”的定义，排除。</p><p>故正确答案为A。</p><p>本题定义内容专业性较强，选项也涉及专业领域知识，仅靠常识较难直接判断。在结合下图资料表述进行匹配，综合关键限定条件比对后，A项更符合定义要求，优选A项。</p><p><img src=\"assets/img/timu/19d29599950b34e.png\" class=\"fig\" style=\"width:700px;height:73px;\"></p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":62,"pid":"p719cd39a01"},{"qid":"16070191","no":13,"type":"定义判断","module":"判断推理","stem":"<p>偏序集是一个集合与其上元素之间的一种关系组成的整体，该关系需满足三个条件：<br>①自反性：集合中每个元素与自身有此关系<br>②反对称性：若元素A与B，B与A互有此关系，则A与B必为同一元素<br>③传递性：若A与B，B与C有此关系，则A与C有此关系<br>根据上述定义，下列属于偏序集的是：</p>","options":[{"k":"A","t":"设集合为一天中所有的时间点，定义集合上的关系为某时间点不晚于另一时间点"},{"k":"B","t":"设集合为书架上所有的书，定义集合上的关系为某本书与另一本书摆在同一层"},{"k":"C","t":"设集合为某班级的所有同学，定义集合上的关系为朋友关系"},{"k":"D","t":"设集合为所有整数，定义集合上的关系为不等于"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“集合中每个元素与自身有此关系”、“若元素A与B，B与A互有此关系，则A与B必为同一元素”、“若A与B，B与C有此关系，则A与C有此关系”。<br>第二步：逐一分析选项。<br>A项：设A、B、C为一天中的三个时间点，即有“A不晚于A，B不晚于B，C不晚于C”，符合“集合中每个元素与自身有此关系”，若“A不晚于B且B不晚于A，可以得到A=B”，符合“若元素A与B，B与A互有此关系，则A与B必为同一元素”，若“A不晚于B，B不晚于C，则A不晚于C”，符合“若A与B，B与C有此关系，则A与C有此关系”，符合定义，当选；<br>B项：设A、B为书架上的两本书，通过“A与B在同一层，B与A在同一层，无法得到A和B一定是同一本书”，不符合“若元素A与B，B与A互有此关系，则A与B必为同一元素”，不符合定义，排除；<br>C项：设A、B、C为班级中的三位同学，若“A和B是朋友，B和C是朋友，无法得到A和C一定是朋友”，不符合“若A与B，B与C有此关系，则A与C有此关系”，不符合定义，排除；<br>D项：任意整数都等于自身，即任意整数和自身都没有“不等于”关系，不符合“集合中每个元素与自身有此关系”，不符合定义，排除。<br>故正确答案为A。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":63,"pid":"p719cd39a01"},{"qid":"16070199","no":14,"type":"定义判断","module":"判断推理","stem":"<p>敏化电极法指的是在指示电极上覆盖一层物质，使电极能提高或改变其选择性，进而检测物质的方法，包括气敏电极法、酶电极法等。其中，气敏电极法在指示电极上覆盖的是特殊的透气膜或空隙间隔，使待测气体可以通过。酶电极法在电极敏感膜上覆盖的是含酶凝胶或悬浮液，待测物可以向酶膜扩散。<br>根据上述定义，下列属于气敏电极法的是：</p>","options":[{"k":"A","t":"<p>在pH电极上覆盖乙烯材料，<img src=\"assets/img/gongshi/formula-a554d51b2b493544.png\" class=\"tex\">气体穿过覆盖物进入中介溶液，引起化学平衡移动，进而计算出浓度</p>"},{"k":"B","t":"<p>某种能将乙醇转化为电流的微生物经培养后可形成微生物膜，当电极放置在膜上时可检测出乙醇的浓度</p>"},{"k":"C","t":"<p>给pH电极装上葡萄糖氧化酶膜，当电极插入待测溶液时，酶催化产生化学反应，进而测定葡萄糖含量</p>"},{"k":"D","t":"<p>在植株鲜样中加偏磷酸溶液，打碎成浆后，取样品滤液加活性炭及硼酸钠溶液，进而测定抗坏血酸含量</p>"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出定义关键词。</p><p>敏化电极法：“指示电极上覆盖一层物质”、“电极能提高或改变其选择性”、“检测物质”；</p><p>气敏电极法：“指示电极上覆盖的是特殊的透气膜或空隙间隔”、“待测气体可以通过”；</p><p>酶电极法：“电极敏感膜上覆盖的是含酶凝胶或悬浮液”、“待测物可以向酶膜扩散”。</p><p>第二步：逐一分析选项。</p><p>A项：在pH电极上覆盖乙烯材料，符合“指示电极上覆盖的是特殊的透气膜或空隙间隔”，<img src=\"assets/img/gongshi/formula-a554d51b2b493544.png\" class=\"tex\">气体穿过覆盖物进入中介溶液，从而计算出浓度，符合“待测气体可以通过”，符合“气敏电极法”定义，当选；</p><p>B项：电极放置在微生物膜上检测出乙醇的浓度，乙醇不属于气体，不符合“待测气体可以通过”，不符合“气敏电极法”定义，排除；</p><p>C项：给pH电极装上葡萄糖氧化酶膜，符合“电极敏感膜上覆盖的是含酶凝胶或悬浮液”，电极插入待测溶液时，酶催化产生化学反应，进而测定葡萄糖含量，符合“待测物可以向酶膜扩散”，符合“酶电极法”定义，不符合“气敏电极法”定义，排除；</p><p>D项：在植株鲜样中加偏磷酸溶液，取样品滤液加活性炭及硼酸钠溶液来测定抗坏血酸含量，不涉及电极，不符合“指示电极上覆盖一层物质”，不符合“敏化电极法”，不符合定义，排除。</p><p>故正确答案为A。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":64,"pid":"p719cd39a01"},{"qid":"16070193","no":15,"type":"定义判断","module":"判断推理","stem":"<p>玻尔兹曼宇宙是玻尔兹曼为了解释宇宙初始阶段的熵之谜提出的假说。基于“整个系统的熵增加，则系统某些部分的熵可以减少”的事实，它设想在宇宙初始物质的随机运动过程中偶然产生一个熵较低的区域，从这个区域诞生了我们所熟知的宇宙。玻尔兹曼大脑假说认为，如果一个新结构可由随机的熵减少所触发产生，那么一个拥有“宇宙记忆”的大脑因为比较简单，所以它的出现概率远比宇宙这种复杂结构的出现概率大得多。<br>根据上述定义，最有可能得出的结论是：</p>","options":[{"k":"A","t":"玻尔兹曼大脑假说是由玻尔兹曼提出的"},{"k":"B","t":"玻尔兹曼宇宙假说认为宇宙可能是唯一的"},{"k":"C","t":"玻尔兹曼大脑假说质疑玻尔兹曼宇宙假说的理论基础"},{"k":"D","t":"玻尔兹曼大脑假说反对存在玻尔兹曼宇宙，主张我们可能只是一些大脑"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>玻尔兹曼宇宙假说：宇宙是随机运动中偶然出现的低熵区域。<br>玻尔兹曼大脑假说：在同样的随机熵减机制下，简单的“大脑”比整个宇宙更容易出现。<br>第二步：逐一分析选项。<br>A项：题干中仅提及了“玻尔兹曼宇宙假说”是由玻尔兹曼提出的，但未提及“玻尔兹曼大脑假说”是由谁提出的，故无法推出，排除； <br>B项：题干中“玻尔兹曼宇宙假说”仅仅是在假设宇宙是如何诞生的，但未提及宇宙是否是唯一的，无法推出，排除；<br>C项：“玻尔兹曼宇宙假说”认为“宇宙”是随机运动偶然产生的，按照这个说法，题干最后一句说随机运动偶然产生的更应该是“简单的大脑”，而非“宇宙”，所以“玻尔兹曼大脑假说”是对“玻尔兹曼宇宙假说”的质疑，可以推出，当选；<br>D项：题干中“玻尔兹曼大脑假说”并未提及我们是否可能是那些拥有“宇宙记忆”的大脑，无法推出，排除。<br>故正确答案为C。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":65,"pid":"p719cd39a01"},{"qid":"17467528","no":16,"type":"类比推理","module":"判断推理","stem":"<p>随波逐流：盲从</p>","options":[{"k":"A","t":"杯水车薪：坚持"},{"k":"B","t":"心不在焉：专注"},{"k":"C","t":"临渊羡鱼：空想"},{"k":"D","t":"据理力争：反驳"}],"answer":"C","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“随波逐流”意思是随着波浪起伏，跟着流水漂荡，比喻没有坚定的立场和主见，随大流；“盲从”意思是盲目地附和、随从别人，二者为近义关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“杯水车薪”意思是用一杯水去救一车着了火的柴草，比喻力量太小或东西太少，无济于事，与“坚持”不是近义关系，与题干逻辑关系不一致，排除；<br>B项：“心不在焉”意思是心思不在这里，思想不集中；“专注”指专心注意，二者是反义关系，与题干逻辑关系不一致，排除；<br>C项：“临渊羡鱼”意思是面对着深渊，希望得到鱼，比喻仅有空想而无实际行动，与“空想”是近义关系，与题干逻辑关系一致，当选；<br>D项：“据理力争”意思是依据道理，竭力维护自己方面的权益、观点等；“反驳”指说出自己的理由来否定别人不同的意见，二者不是近义关系，与题干逻辑关系不一致，排除。<br>故正确答案为C。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":66,"pid":"p719cd39a01"},{"qid":"16069961","no":17,"type":"类比推理","module":"判断推理","stem":"<p>树枝：秸秆：柴火</p>","options":[{"k":"A","t":"车前：沉香：中药"},{"k":"B","t":"尘土：烟雾：污染"},{"k":"C","t":"蚕蛾：蚊子：成虫"},{"k":"D","t":"火车：汽车：车厢"}],"answer":"A","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>树枝和秸秆都是柴火，前两词为并列关系，均与第三词构成种属关系，且树枝、秸秆均为植物类。<br>第二步：判断选项词语间逻辑关系。<br>A项：车前和沉香都是中药，前两词为并列关系，均与第三词构成种属关系，且车前、沉香均为植物类，与题干逻辑关系一致，当选；<br>B项：尘土和烟雾都是污染物，会导致污染，前两词为并列关系，均与第三词构成因果对应关系，与题干逻辑关系不一致，排除；<br>C项：蚕和蚊子是完全变态昆虫，完全变态昆虫的发育需要经历卵、幼虫、蛹、成虫四个时期，蚕蛾和蚊子均是成虫，前两词为并列关系，均与第三词构成种属关系，但蚕和蚊子均为动物类，与题干逻辑关系不一致，排除；<br>D项：火车和汽车都是交通工具，二者为并列关系，车厢为火车和汽车的组成部分，前两词均与第三词构成组成关系，与题干逻辑关系不一致，排除。</p><p>故正确答案为A。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":67,"pid":"p719cd39a01"},{"qid":"16069962","no":18,"type":"类比推理","module":"判断推理","stem":"<p>鸡犬不宁：安居乐业</p>","options":[{"k":"A","t":"羊质虎皮：色厉内荏"},{"k":"B","t":"莺歌燕舞：鸟语花香"},{"k":"C","t":"海底捞针：探囊取物"},{"k":"D","t":"蝇营狗苟：寡廉鲜耻"}],"answer":"C","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“鸡犬不宁”意思是连鸡狗都不得安宁，形容搅扰得很厉害，“安居乐业”意思是安定地生活，愉快地工作，二者为反义关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“羊质虎皮”意思是羊虽然披上虎皮，但怯弱的本性不变，比喻外强内弱，虚有其表，“色厉内荏”意思是外表强横，内心怯懦，形容外表凶恶强横，实际上内心虚弱怯懦，二者为近义关系，与题干逻辑关系不一致，排除；<br>B项：“莺歌燕舞”意思是黄莺歌唱，燕子飞舞，形容大好春光或大好形势，“鸟语花香”意思是鸟儿叫，花儿飘香，多形容春天魅人的景象，二者为近义关系，与题干逻辑关系不一致，排除；<br>C项：“海底捞针”比喻极难找到，“探囊取物”意思是伸手到袋子里取东西，比喻能够轻而易举地办成某件事情，二者为反义关系，与题干逻辑关系一致，当选；<br>D项：“蝇营狗苟”意思是像苍蝇那样飞来飞去，像狗那样苟且偷生，形容人不顾廉耻，到处钻营，“寡廉鲜耻”意思是不廉洁，不知羞耻，二者为近义关系，与题干逻辑关系不一致，排除。<br>故正确答案为C。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":68,"pid":"p719cd39a01"},{"qid":"16070195","no":19,"type":"类比推理","module":"判断推理","stem":"<p>（    ）对于 庐山 相当于 车水马龙 对于（    ）</p>","options":[{"k":"A","t":"游人如织 街市"},{"k":"B","t":"惊鸿一瞥 人群"},{"k":"C","t":"天然画卷 剧场"},{"k":"D","t":"鬼斧神工 陋巷"}],"answer":"A","multi":false,"explanation":"<p>逐一代入选项。<br>A项：游人如织形容游人多得像织布的线一样，密密麻麻，可以用来形容庐山的景象，二者为特点与描述对象的对应关系；车水马龙指车如流水，马如游龙一般，形容热闹繁华的景象，可以用来形容街市，二者为特点与描述对象的对应关系，前后逻辑关系一致，当选；<br>B项：惊鸿一瞥指人只是匆匆看了一眼，却给人留下极深的印象，与庐山无明显逻辑关系；车水马龙指车如流水，马如游龙一般，形容热闹繁华的景象，不能用来形容人群，前后逻辑关系不一致，排除；<br>C项：天然画卷指自然形成的、未经人工加工修饰的美丽景观，可以用来形容庐山的景象；车水马龙指车如流水，马如游龙一般，形容热闹繁华的景象，不能用来形容剧场，前后逻辑关系不一致，排除；<br>D项：鬼斧神工原意是像鬼神制作出来的，形容艺术技巧高超，不像是人力所能达到的，可以用来形容庐山的景象；车水马龙指车如流水，马如游龙一般，形容热闹繁华的景象，不能用来形容陋巷，前后逻辑关系不一致，排除。<br>故正确答案为A。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":69,"pid":"p719cd39a01"},{"qid":"17467537","no":20,"type":"类比推理","module":"判断推理","stem":"<p>光刻机 对于 （    ） 相当于 （    ） 对于 核燃料</p>","options":[{"k":"A","t":"芯片  离心机"},{"k":"B","t":"计算器  核电站"},{"k":"C","t":"光盘  压铸机"},{"k":"D","t":"紫外线光源  核裂变"}],"answer":"A","multi":false,"explanation":"<p>逐一代入选项。<br>A项：光刻机是生产芯片的设备，二者为生产设备与产品的对应关系；离心机是生产核燃料的设备，二者为生产设备与产品的对应关系，前后逻辑关系一致，当选；<br>B项：光刻机是生产计算器中的芯片的设备，二者对应关系；核燃料是核电站的能量来源，二者为能量来源的对应关系，前后逻辑关系不一致，排除；<br>C项：光刻机是生产芯片的设备，光盘是一种利用激光扫描记录和读取信息的光学存储介质，二者没有明显逻辑关系；压铸机是用于压力铸造的机器，核燃料是可在核反应堆中通过核裂变或核聚变释放核能的材料，二者没有明显逻辑关系，前后逻辑关系不一致，排除；<br>D项：紫外线光源是光刻机的组成部分，二者为组成关系；核裂变是核燃料释放能量的方式，二者为对应关系，前后逻辑关系不一致，排除。<br>故正确答案为A。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":70,"pid":"p719cd39a01"},{"qid":"16070200","no":21,"type":"逻辑判断","module":"判断推理","stem":"<p>端粒是染色体末端的一段重复的核苷酸序列。当端粒长度变得非常短时，就更容易导致细胞的衰老和凋亡。有研究发现，每天每增加一杯速溶咖啡摄入量，端粒长度对应的等效年龄减少0.38年，因而速溶咖啡摄入量与端粒长度呈负相关。不过，研究结果也显示，研磨咖啡摄入量与端粒长度的相关性没有统计学意义，不能证实研磨咖啡也会减少端粒长度对应的等效年龄。该研究认为，饮用速溶咖啡会导致衰老，饮用研磨咖啡则不会，因而后者更健康。<br>以下哪项如果为真，不能支持上述结论？</p>","options":[{"k":"A","t":"速溶咖啡中往往会添加白砂糖、乳粉等，这些成分容易导致衰老"},{"k":"B","t":"实验中使用的部分速溶咖啡样本，其实是现场研磨咖啡豆制作的"},{"k":"C","t":"与相同量的研磨咖啡相比较，速溶咖啡中导致衰老的铅含量更高"},{"k":"D","t":"制作研磨咖啡时，会使用滤纸吸附咖啡白醇等对人体有害的物质"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：饮用速溶咖啡会导致衰老，饮用研磨咖啡则不会，因而后者更健康。<br>论据：每天每增加一杯速溶咖啡摄入量，端粒长度对应的等效年龄减少0.38年，因而速溶咖啡摄入量与端粒长度呈负相关。不过，研究结果也显示，研磨咖啡摄入量与端粒长度的相关性没有统计学意义，不能证实研磨咖啡也会减少端粒长度对应的等效年龄。<br>本题论点与论据都在说饮用速溶咖啡会导致衰老，但饮用研磨咖啡则不会。论点和论据话题一致，加强优先考虑补充论据，即解释原因或举例子，且本题为选非题，将可以加强的选项排除即可。<br>第二步：逐一分析选项。<br>A项：该项讨论的是速溶咖啡中往往会添加白砂糖、乳粉等，这些成分容易导致衰老，解释了为什么饮用速溶咖啡会导致衰老，补充论据，可以加强，排除；<br>B项：该项讨论的是实验中使用的部分速溶咖啡样本，其实是现场研磨咖啡豆制作的，那么就不确定造成衰老的是否为速溶咖啡，说明实验不科学、不准确，可以削弱，不能加强，当选；<br>C项：该项讨论的是与相同量的研磨咖啡相比较，速溶咖啡中导致衰老的铅含量更高，说明饮用速溶咖啡会导致衰老，饮用研磨咖啡则相较不会，补充论据，可以加强，排除；<br>D项：该项讨论的是制作研磨咖啡时，会使用滤纸吸附咖啡白醇等对人体有害的物质，解释了为什么饮用研磨咖啡会更加健康，补充论据，可以加强，排除。<br>本题为选非题，故正确答案为B。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":71,"pid":"p719cd39a01"},{"qid":"16070197","no":22,"type":"逻辑判断","module":"判断推理","stem":"<p>鱼通过鳃的呼吸作用，从水中吸收钙离子，进入耳石囊内与碳酸根离子结合形成碳酸钙、随后沉积形成耳石，它具有维持鱼身平衡及辅助听觉的作用。鱼耳石的日周轮、年轮和产卵轮等时间记号，记录了鱼类生长过程中的环境信息。通过分析鱼耳石形态和化学组成等方式，我们可以了解鱼类生活史特征及其栖息环境的变化。<br>以下哪项如果为真，最能加强上述论证？</p>","options":[{"k":"A","t":"许多鱼类的寿命可长达数十年之久"},{"k":"B","t":"环境污染可能导致鱼停止生长甚至死亡"},{"k":"C","t":"不同鱼类的耳石大小不同，难以据此判断鱼类的生长环境情况"},{"k":"D","t":"相对于鳞片、鳍条，鱼耳石的形态结构和化学组成更稳定，保存时间更长"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：通过分析鱼耳石形态和化学组成等方式，我们可以了解鱼类生活史特征及其栖息环境的变化。<br>论据：鱼耳石的日周轮、年轮和产卵轮等时间记号，记录了鱼类生长过程中的环境信息。<br>本题论点和论据均在讨论“分析鱼耳石有助于了解鱼类生活的环境”，二者话题一致，加强可以考虑补充论据。<br>第二步：逐一分析选项。<br>A项：该项说的是许多鱼类的寿命很长，而论点讨论的是分析鱼耳石有助于了解鱼类生活的环境，话题不一致，不能加强，排除;<br>B项：该项说的是环境污染对鱼的不良影响，而论点讨论的是分析鱼耳石有助于了解鱼类生活的环境，话题不一致，不能加强，排除;<br>C项：该项说的是根据耳石难以判断鱼类的生长环境，是对论点进行削弱，不能加强，排除;<br>D项：该项说的是鱼耳石形态结构和化学组成更稳定，保存时间更长，补充论据说明鱼耳石在了解鱼类的生活史特征及其栖息环境的变化方面更有优势，可以加强，当选。<br>故正确答案为D。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":72,"pid":"p719cd39a01"},{"qid":"16070201","no":23,"type":"图形推理","module":"判断推理","stem":"<p>近日，考古学家发现了一块展示约1.25亿年前肉食性哺乳动物爬兽袭击较大植食性恐龙鹦鹉嘴龙的化石。化石中，鹦鹉嘴龙呈俯卧姿态，后肢折叠在身体两侧；爬兽的身体向右盘绕，俯坐在鹦鹉嘴龙背侧，抓扒着猎物的下巴并撕咬肋骨，其小腿则被鹦鹉嘴龙的后腿夹住。研究者认为，这一发现挑战了“恐龙在白垩纪期间几乎没有受到同时代哺乳动物威胁”的观点。<br>以下哪项如果为真，最不能支持上述研究者的结论？</p>","options":[{"k":"A","t":"已能够确认爬兽与鹦鹉嘴龙纠缠在一起并同时葬身于火山喷发"},{"k":"B","t":"在发现该标本前就有其他观点认为爬兽会捕食鹦鹉嘴龙等恐龙"},{"k":"C","t":"通过恐龙骨架上的牙印证明了爬兽当时正啃食鹦鹉嘴龙的尸体"},{"k":"D","t":"在一块爬兽标本的胃中曾发现有鹦鹉嘴龙幼年个体的骨骼残留"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出论点和论据。</p><p>论点：恐龙在白垩纪期间受到过同时代哺乳动物威胁。</p><p>论据：考古学家发现了一块展示约1.25亿年前肉食性哺乳动物爬兽袭击较大植食性恐龙鹦鹉嘴龙的化石。化石中，鹦鹉嘴龙呈俯卧姿态，后肢折叠在身体两侧；爬兽的身体向右盘绕，俯坐在鹦鹉嘴龙背侧，抓扒着猎物的下巴并撕咬肋骨，其小腿则被鹦鹉嘴龙的后腿夹住。</p><p>从论据“化石显示二者身体纠缠在一起”到论点“恐龙受到过威胁”，注意身体纠缠<img src=\"assets/img/gongshi/formula-3ed54294e1dced6a.png\" class=\"tex\">威胁，所以论据到论点的推理是有漏洞的，可以补充论据填补漏洞，也可以直接加强论点。</p><p>第二步：逐一分析选项。</p><p>A项：该项指出能够确认爬兽与鹦鹉嘴龙纠缠在一起，论据讨论的也是二者在化石中呈现的纠缠在一起的形态，所以该项的表述是对论据内容的重复，保留；</p><p>B项：该项指出在发现该标本前就有其他观点认为爬兽会捕食恐龙，补充了其他观点的论据说明哺乳动物对恐龙有威胁，保留；</p><p>C项：该项指出可证明爬兽当时正啃食鹦鹉嘴龙的尸体，结合论据中“二者身体纠缠在一起”的表述，说明在鹦鹉嘴龙死之前有和爬兽纠缠的过程，可体现出哺乳动物对恐龙的威胁，保留；</p><p>D项：该项指出在爬兽标本的胃中发现有鹦鹉嘴龙幼年个体的骨骼残留，结合论据中“二者身体纠缠在一起”的表述，说明爬兽对恐龙有威胁，保留；</p><p>对比四个选项，从论据“纠缠”到论点“威胁”，</p><p>A还在说纠缠，重复论据</p><p>B举例加强论点，确实在捕食，有威胁</p><p>论据（纠缠）+C（捕食），可以推出论点（威胁）</p><p>论据（纠缠）+D（捕食），可以推出论点（威胁）</p><p>B、C、D三项均从其他角度补充了论据，证明了可能有“威胁”，只有A项是对题干论据的重复，对于加强而言，补充其他角度的论据比单纯重复题干论据更有说服力，因此，对比择优，A项最不能支持。</p><p>本题为选非题，故正确答案为A。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":73,"pid":"p719cd39a01"},{"qid":"16070289","no":24,"type":"逻辑判断","module":"判断推理","stem":"<p>紫杉醇是治疗癌症的明星药物。紫杉醇通过作用于细胞内的微管蛋白，保持微管的稳定性来抑制细胞的有丝分裂，控制癌细胞发展，从而达到治疗目的。香榧中含有紫杉醇，因此，有观点认为，多食用香榧可以治疗癌症。<br>以下哪项如果为真，最能削弱上述结论？</p>","options":[{"k":"A","t":"紫杉醇对正常细胞产生的影响目前还未可知"},{"k":"B","t":"香榧中紫杉醇含量微乎其微，几乎可以忽略不计"},{"k":"C","t":"香榧含有丰富的蛋白质，可以增强癌症患者的免疫力"},{"k":"D","t":"对于分裂速度比正常细胞快的癌细胞，紫杉醇表现出更明显的抑制作用"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：多食用香榧可以治疗癌症。<br>论据：香榧中含有紫杉醇，紫杉醇通过作用于细胞内的微管蛋白，保持微管的稳定性来抑制细胞的有丝分裂，控制癌细胞发展，从而达到治疗目的。<br>本题论点在讨论“多食用香榧可以治疗癌症”，论据在讨论“香榧中的紫杉醇能治疗癌症”，论点和论据话题不一致，削弱优先考虑拆桥，即拆断“食用香榧”和“紫杉醇”之间的联系。<br>第二步：逐一分析选项。<br>A项：该项指出“紫杉醇对正常细胞产生的影响目前还未可知”，而题干讨论的是“紫杉醇对癌细胞的影响”，话题不一致，无法削弱，排除；<br>B项：论点讨论的是“多食用香榧可以治疗癌症”，原因是“香榧中的紫杉醇能治疗癌症”，该项指出“香榧中紫杉醇含量微乎其微，几乎可以忽略不计”，即不能通过日常食用香榧取得治疗癌症的效果，断开了论点和论据之间的联系，为拆桥项，可以削弱，当选；<br>C项：该项指出“香榧可以增强癌症患者的免疫力”，但增强免疫力不等于可以治疗癌症，话题不一致，无法削弱，排除；<br>D项：该项指出“紫杉醇能抑制癌细胞”，补充论据，为加强项，无法削弱，排除。<br>故正确答案为B。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":74,"pid":"p719cd39a01"},{"qid":"16070203","no":25,"type":"逻辑判断","module":"判断推理","stem":"<p>一项关于离子通道Piezo2的介导性慢性疼痛超敏反应功能的研究表明，Piezo2是一个机械敏感通道，会在压力的刺激下激活伤害性感受器，当Piezo2发生功能丧失型突变时，患者对轻微的触摸或振动不再敏感；当它发生功能获得型突变时，患者通常被诊断为其它疾病。<br>以下哪项如果为真，最能削弱上述结论？</p>","options":[{"k":"A","t":"有的慢性疼痛综合征患者的伤害性感受器在无机械刺激时仍然活跃"},{"k":"B","t":"有的Piezo2功能丧失型突变患者在强烈挤压皮肤时激活了伤害性感受器"},{"k":"C","t":"有的患者发生Piezo2功能获得型突变，被诊断出患有复杂发育障碍疾病"},{"k":"D","t":"有的患者发生Piezo2功能丧失型突变，伤害性感受器对机械刺激更敏感"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：Piezo2是一个机械敏感通道，会在压力的刺激下激活伤害性感受器，当Piezo2发生功能丧失型突变时，患者对轻微的触摸或振动不再敏感；当它发生功能获得型突变时，患者通常被诊断为其它疾病。<br>论据：无。<br>本题论点讨论的是Piezo2会在压力的刺激下激活伤害性感受器，并给出Piezo2功能丧失型突变和功能获得型突变的两种表现。只有论点，没有论据，削弱优先考虑削弱论点。<br>第二步：逐一分析选项。<br>A项：该项指出有的慢性疼痛综合征患者伤害性感受器在“无机械刺激时”仍活跃，而论点讨论的是Piezo2通道在“压力刺激时”的表现，话题不一致，无法削弱，排除；<br>B项：该项指出有的Piezo2功能丧失型突变患者在“强烈挤压皮肤时”激活了伤害性感受器，但不明确其在“轻微的触摸或振动时”是否能激活伤害性感受器，不明确选项，无法削弱，排除；<br>C项：该项指出有的患者发生Piezo2功能获得型突变，被诊断出患有复杂发育障碍疾病，对论点中“发生功能获得型突变时，患者通常被诊断为其它疾病”进行支持，具有一定加强力度，无法削弱，排除；<br>D项：该项指出有的患者发生Piezo2功能丧失型突变，伤害性感受器对机械刺激更敏感，举例削弱论点中“Piezo2发生功能丧失型突变时，患者对轻微的触摸或振动不再敏感”，削弱论点，可以削弱，当选。<br>故正确答案为D。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":75,"pid":"p719cd39a01"},{"qid":"16070213","no":26,"type":"逻辑判断","module":"判断推理","stem":"<p>某研究团队发布了一项关于视觉感知对热舒适判断影响机制的研究，研究选取典型景观实景照片在实验室进行视觉刺激实验，从心理、行为、生理三个维度展开互证，发现人们通过快速扫视捕获热环境相关景观要素信息，视觉感知信息结合个体热联想经验会转换为热舒适判断，且视觉刺激引发的皮电变化率与阴影、植物总体占比率呈显著正相关，说明阴影和植物总体占比率可能是影响公园热舒适体验的关键因素。<br>要使上述结论成立，还需基于以下哪一前提?</p>","options":[{"k":"A","t":"光照强度变化不会通过非视觉途径影响皮电反应及热舒适判断"},{"k":"B","t":"阴影和植物总体占比率高的区域，实际热环境温度通常更低"},{"k":"C","t":"个体热联想经验主要源于日常生活中的户外环境体验"},{"k":"D","t":"皮电变化率可作为衡量人体热舒适感受的指标"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：阴影和植物总体占比率可能是影响公园热舒适体验的关键因素。<br>论据：人们通过快速扫视捕获热环境相关景观要素信息，视觉感知信息结合个体热联想经验会转换为热舒适判断，且视觉刺激引发的皮电变化率与阴影、植物总体占比率呈显著正相关。<br>本题论点讨论的是“阴影和植物总体占比率”和“热舒适体验”之间的关系，论据讨论的是“皮电变化率”和“阴影和植物总体占比率”之间的关系，二者话题不一致，加强优先考虑搭桥，即在“热舒适体验”和“皮电变化率”之间建立联系。<br>第二步：逐一分析选项。<br>A项：该项强调的是光照强度变化不会通过非视觉途径影响皮电反应及热舒适判断，说明实验中关于视觉感知对热舒适判断的影响研究是严谨的，有一定的加强力度，但不是上述论证成立的前提，排除；<br>B项：该项强调的是阴影和植物总体占比率高的区域实际温度反而更低，而论点讨论的是影响公园热舒适体验的关键因素是阴影和植物总体占比率，话题不一致，无法加强，排除；<br>C项：该项指出个体热联想经验的来源是户外环境体验，而论点讨论的是影响公园热舒适体验的关键因素是阴影和植物总体占比率，话题不一致，无法加强，排除；<br>D项：该项指出衡量人体热舒适感受的指标是皮电变化率，建立了“皮电变化率”和“热舒适体验”之间的联系，为搭桥项，是论证成立的前提，当选。<br>故正确答案为D。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":76,"pid":"p719cd39a01"},{"qid":"16070293","no":27,"type":"逻辑判断","module":"判断推理","stem":"<p>研究人员发现，与摄入盐水的对照组小鼠相比，摄入葡萄球菌肠毒素SEA的小鼠会出现明显干呕现象。人类癌症患者使用化疗药物也会有类似的恶心和呕吐反应。研究显示，小鼠肠道内的SEA毒素激活了肠内壁的肠嗜铬细胞，释放出血清素，血清素又与肠道的感觉神经元受体结合，将信号传递到脑干中的特定神经元从而引发干呕，当特定神经元被灭活后，小鼠干呕显著减少。研究还发现，特定神经元被灭活后，其他动物的干呕也会显著减少。<br>由此可以推出：</p>","options":[{"k":"A","t":"如果不摄入葡萄球菌肠毒素，那么小鼠就不会出现干呕现象"},{"k":"B","t":"开发出灭活特定神经元的药物或能帮助化疗病人减少呕吐"},{"k":"C","t":"SEA毒素与肠道的感觉神经元受体结合会引发动物的干呕"},{"k":"D","t":"切断小鼠脑干中特定神经元的信号传递或能引发干呕"}],"answer":"B","multi":false,"explanation":"<p>日常结论题，根据题干信息逐一分析选项。<br>A项：题干指出“摄入葡萄球菌肠毒素SEA的小鼠会出现明显干呕现象”，并未提到不摄入葡萄球菌肠毒素的情况，无法推出，排除；<br>B项：题干指出“人类癌症患者使用化疗药物也会有类似的恶心和呕吐反应”和“当特定神经元被灭活后，小鼠干呕显著减少。研究还发现，特定神经元被灭活后，其他动物的干呕也会显著减少”，说明灭活特定神经元能减少动物干呕，而化疗呕吐与此相似，因此开发出灭活特定神经元的药物有可能帮助化疗病人减少呕吐，可以推出，当选；<br>C项：题干指出“小鼠肠道内的SEA毒素激活了肠内壁的肠嗜铬细胞，释放出血清素，血清素又与肠道的感觉神经元受体结合，将信号传递到脑干中的特定神经元从而引发干呕”，说明与受体结合的是血清素，并非SEA毒素，无法推出，排除；<br>D项：题干指出“当特定神经元被灭活后，小鼠干呕显著减少”，说明切断信号传递能够减少干呕，而非引发干呕，无法推出，排除。<br>故正确答案为B。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":77,"pid":"p719cd39a01"},{"qid":"16070292","no":28,"type":"逻辑判断","module":"判断推理","stem":"<p>我国幅员辽阔，物产丰富。2022年海洋原油产量5800万吨，但是缺少高精度海洋勘测设备和技术，这严重制约了国家海洋油气勘探开发进程。2023年我国自主研发的海底地震勘探采集设备——“海脉”在渤海投入使用，这将极大提升我国海洋油气藏勘探精度。由此可以预期我国海洋原油产量将会提升。<br>以下哪项是上述论证成立的必要前提？</p>","options":[{"k":"A","t":"<p>“海脉”可以“看”清埋藏几千米深的陆地油气储层</p>"},{"k":"B","t":"<p>“海脉”能捕捉到海底相当于蚊子声<img src=\"assets/img/gongshi/formula-ce05661947f821dc.png\" class=\"tex\">大小的信号</p>"},{"k":"C","t":"<p>当前我国已经具有开采海洋原油的各项技术、设备和能力</p>"},{"k":"D","t":"<p>成千上万个“海脉”节点采集的数据信息可以处理成地震剖面</p>"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：我国海洋原油产量将会提升。<br>论据：“海脉”在渤海投入使用，这将极大提升我国海洋油气藏勘探精度。<br>本题论点讨论的是我国海洋原油产量将会提升，论据讨论的是“海脉”的使用将极大提升我国海洋油气藏勘探精度，二者话题不一致，提问为“必要前提”，加强优先考虑搭桥和补充必要条件。<br>A项：该项指出“海脉”可以“看”清陆地油气储层，但并未说明“看”清陆地油气储层是否能提升我国海洋原油产量，为不明确项，无法加强，排除；<br>B项：该项指出“海脉”能捕捉到海底的微弱信号，但并未说明捕捉到海底的微弱信号是否能提升我国海洋原油产量，为不明确项，无法加强，排除；<br>C项：该项指出我国已经具有开采海洋原油的各项技术、设备和能力，只有具备开采能力，勘探精度提升才能带来产量提升，如果我国不具备开采海洋原油的各项技术、设备和能力，那么即使勘探精度提升，产量也无法提升，因此该项是论点成立的必要条件，当选；<br>D项：该项指出成千上万个“海脉”节点采集的数据信息可以处理成地震剖面，但并未说明得到的地震剖面是否能提升我国海洋原油产量，为不明确项，无法加强，排除。<br>故正确答案为C。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":78,"pid":"p719cd39a01"},{"qid":"16070296","no":29,"type":"逻辑判断","module":"判断推理","stem":"<p>甲、乙、丙、丁、戊、己、庚7人分别去P、Q、R、S四个不同的值班点，根据工作安排，每个值班点至少有1人，至多有3人；每个人只能去1个值班点；要求Q值班点有3人值班。同时，还需满足下列条件：<br>（1）去R值班点的人数与去P值班点的人数一样<br>（2）如果甲、乙、丙中至多2人去Q值班点，那么只有丁去S值班点<br>（3）只有乙和庚去S值班点，丁或戊才不去S值班点<br>根据上述信息，下列哪项必然为真？</p>","options":[{"k":"A","t":"乙去Q值班点，戊去S值班点"},{"k":"B","t":"甲去Q值班点，丁去P值班点"},{"k":"C","t":"己去P值班点，庚去R值班点"},{"k":"D","t":"丙去P值班点，戊去S值班点"}],"answer":"A","multi":false,"explanation":"<p>第一步：分析题干条件。</p><p>（1）甲、乙、丙、丁、戊、己、庚7人去P、Q、R、S四个值班点，每个值班点至少有1人，至多有3人，每个人只能去1个值班点，Q值班点有3人；</p><p>（2）R值班点人数=P值班点人数；</p><p>（3）甲、乙、丙至多2人去Q值班点<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">只有丁去S值班点；</p><p>（4）丁 或 戊不去S值班点<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">乙和庚去S值班点。</p><p>第二步：根据题干条件进行推理。</p><p>由条件（1）（2）可确定各值班点的人数为Q值班点3人、S值班点2人、P值班点1人、R值班点1人。S值班点2人是对条件（3）的否后，否后必否前，可推知甲、乙、丙3人均去Q值班点。乙去Q值班点，就不能再去S值班点，是对条件（4）的否后，否后必否前，可推知丁、戊均去S值班点。己、庚的值班点无法确定，只有A项必然为真。</p><p>故正确答案为A。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":79,"pid":"p719cd39a01"},{"qid":"17467534","no":30,"type":"逻辑判断","module":"判断推理","stem":"<p>青藏高原被誉为“亚洲水塔”，是全球气候变化敏感区和指示区。这里分布着地球海拔最高数量最多的高原湖泊群，面积约占全国的百分之五十，对区域水循环、生态环境和气候调节具有重要意义。如果青藏高原降水增加或者冰川加速消融，那么青藏高原的湖泊将会持续扩张，并且导致潜在的流域合并或重组，威胁到该地区的基础设施和生态安全。由此可以推出：</p>","options":[{"k":"A","t":"如果青藏高原的湖泊没有持续扩张，那么青藏高原的降水没有增加且冰川并没有加速消融"},{"k":"B","t":"如果青藏高原降水增加或者冰川加速消融，将会导致其潜在的流域合并"},{"k":"C","t":"如果青藏高原降水没有增加，那么其潜在的流域没有合并和重组"},{"k":"D","t":"如果青藏高原的流域合并或重组，那么青藏高原降水增加"}],"answer":"A","multi":false,"explanation":"<p>第一步：翻译题干。</p><p>青藏高原降水增加 或 冰川加速消融<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">（青藏高原的湖泊将会持续扩张） 且 （潜在的流域合并 或 重组）。</p><p>第二步：逐一分析选项。</p><p>A项：翻译为：<img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">青藏高原的湖泊将会持续扩张<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">青藏高原降水增加 且 <img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">冰川加速消融，是否定题干箭头后“且关系”的一部分，否后必否前，可以推出，当选；</p><p>B项：翻译为：青藏高原降水增加 或 冰川加速消融<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">潜在的流域合并，是对题干的肯前，肯前必肯后，应推出“潜在的流域合并 或 重组”，而非“潜在的流域合并”，不能推出，排除；</p><p>C项：翻译为：<img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">青藏高原降水增加<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">潜在的流域合并和重组，是否定题干箭头前“或关系”的一部分，不是否前，且否前得不到确定结论，不能推出，排除；</p><p>D项：翻译为：青藏高原的流域合并 或 重组<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">青藏高原降水增加，是肯定题干箭头后“且关系”的一部分，不是肯后，且肯后得不到确定结论，不能推出，排除。</p><p>故正确答案为A。</p>","from":{"file":"2026年山西省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":80,"pid":"p719cd39a01"}]};
